A,CAEA,wBACE,SAAA,CACA,4BAAA,CAMN,eACE,YAAA,CACA,kBAAA,CACA,OAAA,CAIF,cACE,cAAA,CACA,0BAAA,CACA,UAAA,CAIF,cACE,WAAA,CACA,aAAA,CACA,QAAA,CACA,wCAAA,CACA,uCAAA,CACA,iBAAA,CACA,0BAAA,CACA,cAAA,CACA,gBAAA,CACA,qBAAA,CACA,cAAA,CACA,uBAAA,CAEA,oBACE,YAAA,CACA,mCAAA,CAGF,oBACE,mCAAA,CAGF,qBAEE,4BAAA,CACA,0BAAA,CAIF,sBACE,eAAA,CACA,eAAA,CAIF,sBACE,cAAA,CACA,cAAA,CAKJ,cACE,UAAA,CACA,WAAA,CACA,mBAAA,CACA,YAAA,CACA,kBAAA,CACA,sBAAA,CACA,wBAAA,CACA,WAAA,CACA,iBAAA,CACA,cAAA,CACA,uBAAA,CAEA,gBACE,cAAA,CACA,0BAAA,CACA,WAAA,CACA,uBAAA,CAGF,oBACE,6BAAA,CAEA,sBACE,SAAA,CAIJ,qBACE,8BAAA,CAKJ,oDAEE,6CAAA,CAGF,8CAEE,SAAA,CACA,0BAAA,CAGF,8CAEE,SAAA,CACA,uBAAA',sourcesContent:['
.floating-panel-root {
  position: fixed;
  // 降低 z-index，使其在聊天面板下方
  z-index: 50;
  pointer-events: none;
  display: flex;
  align-items: center;

  // 默认使用 right 定位（吸附模式）
  right: var(--fp-right-position, 0);
  top: 5px;

  // 自由悬浮模式：使用 left/top 定位
  &.floating-mode {
    right: auto;
    left: var(--fp-left-position, 100px);
    top: var(--fp-top-position, 5px);
    // 固定宽度，让收起时 edge-tab 能通过 margin-left: auto 靠右对齐
    width: 328px;
    // 顶部对齐，避免收起/展开时因高度变化导致垂直位置跳动
    align-items: flex-start;
  }

  * {
    pointer-events: auto;
  }
}

// 拖拽时的样式
.floating-panel-root.dragging {
  .panel-wrapper,
  .edge-tab {
    opacity: 0.8;
  }
}

// 边缘标签（收起状态，在右边）- 高度与展开面板一致，支持拖拽
.edge-tab {
  width: 14px;
  height: 42px;
  background: var(--fp-glass-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--fp-border-color);
  border-right: none;
  border-radius: 8px 0 0 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.85;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow:
    -2px 0 12px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -1px 0 rgba(0, 0, 0, 0.1);

  i {
    font-size: 10px;
    color: var(--fp-text-color);
    opacity: 0.8;
    transition: all 0.25s ease;
  }

  &:hover {
    width: 20px;
    opacity: 1;
    background: var(--fp-glass-hover-bg);
    box-shadow:
      -3px 0 16px rgba(0, 0, 0, 0.3),
      inset 0 1px 0 rgba(255, 255, 255, 0.12),
      inset 0 -1px 0 rgba(0, 0, 0, 0.15);

    i {
      opacity: 1;
      color: var(--fp-accent-color);
    }
  }

  &:active {
    width: 12px;
    opacity: 0.9;
  }

  // 自由悬浮模式下：正方形圆角小块，拖拽光标
  .floating-mode & {
    // 改为正方形
    width: 32px;
    height: 32px;
    cursor: grab;

    &:active {
      cursor: grabbing;
    }
    border: 1px solid var(--fp-border-color);
    border-radius: 8px;
    box-shadow:
      0 2px 12px rgba(0, 0, 0, 0.25),
      inset 0 1px 0 rgba(255, 255, 255, 0.08),
      inset 0 -1px 0 rgba(0, 0, 0, 0.1);

    i {
      font-size: 12px;
    }

    &:hover {
      // 悬停时不改变尺寸
      width: 32px;
      box-shadow:
        0 3px 16px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.12),
        inset 0 -1px 0 rgba(0, 0, 0, 0.15);
    }

    &:active {
      // 点击时也不改变尺寸
      width: 32px;
    }

    // 自由悬浮模式收起时，让 edge-tab 靠右对齐
    // 这样收起后位置与展开时的右边缘一致
    margin-left: auto;
  }
}

// 整个面板容器（统一背景，解决分界线问题）
.panel-wrapper {
  display: flex;
  flex-direction: column;
  // 固定宽度，不随内容变化
  width: 328px;

  // 统一的毛玻璃背景 - 头部和下拉内容共享同一个背景
  background: var(--fp-glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);

  // 边框和圆角（吸附模式：右侧无边框）
  border: 1px solid var(--fp-border-color);
  border-right: none;
  border-radius: 12px 0 0 12px;

  // 阴影设计：与集成控件 EdgePanel 保持一致
  box-shadow:
    -4px 0 20px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -1px 0 rgba(0, 0, 0, 0.1);

  overflow: hidden;

  // 当下拉面板打开时，调整圆角
  &.dropdown-open {
    border-radius: 12px 0 0 12px;
  }

  // 自由悬浮模式下：完整边框和圆角
  .floating-mode & {
    border: 1px solid var(--fp-border-color);
    border-radius: 12px;
    box-shadow:
      0 4px 20px rgba(0, 0, 0, 0.3),
      inset 0 1px 0 rgba(255, 255, 255, 0.08),
      inset 0 -1px 0 rgba(0, 0, 0, 0.1);

    &.dropdown-open {
      border-radius: 12px;
    }
  }
}

// 头部工具栏（无背景，继承父容器背景）
.panel-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px;
  cursor: pointer;
  // 无背景色，无边框 - 完全透明，继承 .panel-wrapper 的背景

  // 自由悬浮模式下的拖拽样式
  &--draggable {
    cursor: grab;

    &:active {
      cursor: grabbing;
    }
  }
}

// 分隔线
.panel-divider {
  width: 1px;
  height: 18px;
  background: var(--fp-border-color);
  opacity: 0.4;
  margin: 0 2px;
}

// 收起按钮（在右边）
.panel-collapse {
  width: 16px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.2s ease;

  i {
    font-size: 10px;
    color: var(--fp-text-color);
    opacity: 0.6;
    transition: all 0.2s ease;
  }

  &:hover {
    background: rgba(255, 255, 255, 0.08);

    i {
      opacity: 1;
      color: var(--fp-accent-color);
    }
  }
}

// 面板区块
.panel-section {
  display: flex;
  align-items: center;
  gap: 4px;
}

// 区块图标
.section-icon {
  font-size: 10px;
  color: var(--fp-text-color);
  opacity: 0.8;
}

// 下拉选择框 - 使用半透明卡片背景色
.panel-select {
  height: 26px;
  padding: 0 8px;
  margin: 0;
  background: var(--fp-card-bg-translucent);
  border: 1px solid var(--fp-border-color);
  border-radius: 6px;
  color: var(--fp-text-color);
  font-size: 12px;
  line-height: 24px;
  vertical-align: middle;
  cursor: pointer;
  transition: all 0.2s ease;

  &:focus {
    outline: none;
    border-color: var(--fp-accent-color);
  }

  &:hover {
    border-color: var(--fp-accent-color);
  }

  option {
    // option 元素需要实色背景，否则下拉菜单会透明
    background: var(--fp-card-bg);
    color: var(--fp-text-color);
  }

  // 预设选择器样式
  &--preset {
    min-width: 100px;
    max-width: 160px;
  }

  // 分支选择器样式
  &--branch {
    min-width: 60px;
    max-width: 90px;
  }
}

// 操作按钮 - 无边框，只有图标
.panel-action {
  width: 26px;
  height: 26px;
  margin: 1px -6px 0 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;

  i {
    font-size: 13px;
    color: var(--fp-text-color);
    opacity: 0.85;
    transition: all 0.2s ease;
  }

  &:hover {
    background: rgba(255, 255, 255, 0.1);

    i {
      opacity: 1;
    }
  }

  &:active {
    background: rgba(255, 255, 255, 0.05);
  }
}

// 面板滑入动画（从右向左展开）
.panel-slide-enter-active,
.panel-slide-leave-active {
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.panel-slide-enter-from,
.panel-slide-leave-to {
  opacity: 0;
  transform: translateX(20px);
}

.panel-slide-enter-to,
.panel-slide-leave-from {
  opacity: 1;
  transform: translateX(0);
}
