// 导入共享样式
@import '../styles/shared-styles.scss';

// 遮罩层
.pm-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  animation: pm-overlay-fade-in 0.2s ease-out;
}

// 主面板容器
.pm-panel-container {
  position: relative;
  display: flex;
  align-items: stretch;
  gap: 0;
  transition: gap 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  // 缝合模式下的布局 - 两个面板之间有间距
  &--merge-mode {
    gap: 80px;

    // 侧边栏收缩时减小间距
    &.pm-panel-container--sidebar-collapsed {
      gap: 20px;
    }
  }

  // 分支模式下的布局 - 与缝合模式相同
  &--branch-mode {
    gap: 80px;

    // 侧边栏收缩时减小间距
    &.pm-panel-container--sidebar-collapsed {
      gap: 20px;
    }
  }

  // 收藏模式下的布局 - 与缝合模式相同
  &--favorite-mode {
    gap: 80px;

    // 侧边栏收缩时减小间距
    &.pm-panel-container--sidebar-collapsed {
      gap: 20px;
    }
  }
}

// 主面板包装器（包含主面板和侧边栏）
.pm-main-wrapper {
  position: relative;
  display: flex;
  align-items: stretch;
}

// 缝合面板滑入动画（使用公共动画）
.merge-panel-slide-enter-active {
  animation: pm-panel-in 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.merge-panel-slide-leave-active {
  animation: pm-panel-out 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

// 主面板弹出动画 - 快速平滑的缩放+淡入
.panel-pop-enter-active {
  animation: pm-panel-pop-in 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.panel-pop-leave-active {
  animation: pm-panel-pop-out 0.15s ease-in;
}

@keyframes pm-panel-pop-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes pm-panel-pop-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}
