.side-panel-root {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%) translateX(100%);
  z-index: 20;
  display: flex;
  align-items: center;
  pointer-events: none;

  * {
    pointer-events: auto;
  }
}

// 收起状态的小标签
.side-tab {
  width: 16px;
  height: 48px;
  background: var(--pm-glass-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--pm-border);
  border-left: none;
  border-radius: 0 8px 8px 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.85;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow:
    2px 0 12px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -1px 0 rgba(0, 0, 0, 0.1);

  i {
    font-size: 10px;
    color: var(--pm-text-primary);
    opacity: 0.7;
    transition: all 0.25s ease;
  }

  &:hover {
    width: 22px;
    opacity: 1;
    background: var(--pm-glass-hover-bg, rgba(255, 255, 255, 0.12));
    box-shadow:
      3px 0 16px rgba(0, 0, 0, 0.3),
      inset 0 1px 0 rgba(255, 255, 255, 0.12),
      inset 0 -1px 0 rgba(0, 0, 0, 0.15);

    i {
      opacity: 1;
      color: var(--pm-quote-color);
    }
  }

  &:active {
    width: 14px;
    opacity: 0.9;
  }
}

// 展开状态的面板
.side-panel-content {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  background: var(--pm-glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--pm-border);
  border-left: none;
  border-radius: 0 12px 12px 0;
  box-shadow:
    4px 0 20px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 -1px 0 rgba(0, 0, 0, 0.1);
}

// 收起按钮
.panel-collapse {
  width: 100%;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.2s ease;
  margin-bottom: 2px;

  i {
    font-size: 10px;
    color: var(--pm-text-primary);
    opacity: 0.4;
    transition: all 0.2s ease;
  }

  &:hover {
    background: rgba(255, 255, 255, 0.08);

    i {
      opacity: 1;
      color: var(--pm-quote-color);
    }
  }
}

// 按钮容器
.panel-buttons {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

// 功能按钮 - 简洁风格，无背景无边框
.panel-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 10px 16px;
  background: transparent;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;

  i {
    font-size: 16px;
    color: var(--pm-text-primary);
    opacity: 0.7;
    transition: all 0.2s ease;
  }

  .btn-label {
    font-size: 12px;
    color: var(--pm-text-primary);
    opacity: 0.7;
    transition: all 0.2s ease;
  }

  &:hover {
    background: rgba(255, 255, 255, 0.06);

    i,
    .btn-label {
      opacity: 1;
    }
  }

  &:active {
    background: rgba(255, 255, 255, 0.03);
  }

  // 激活状态（缝合模式开启时）
  &--active {
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid var(--pm-quote-color);

    i {
      color: var(--pm-quote-color);
      opacity: 1;
    }

    .btn-label {
      color: var(--pm-quote-color);
      opacity: 1;
    }

    &:hover {
      background: rgba(255, 255, 255, 0.12);
    }
  }
}

// 面板滑入动画（从左向右展开）
.side-panel-slide-enter-active,
.side-panel-slide-leave-active {
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.side-panel-slide-enter-from,
.side-panel-slide-leave-to {
  opacity: 0;
  transform: translateX(-20px);
}

.side-panel-slide-enter-to,
.side-panel-slide-leave-from {
  opacity: 1;
  transform: translateX(0);
}
