  }
}

// 导入导出按钮区域
.title-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

// 按钮分隔线
.title-actions-divider {
  width: 1px;
  height: 12px;
  background: rgba(255, 255, 255, 0.15);
  margin: 0 4px;
}

.title-action-btn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 0;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--pm-text-secondary);
  font-size: 10px;
  opacity: 0.6;
  transition: all 0.2s ease;

  i {
    font-size: 10px;
  }

  &:hover:not(:disabled) {
    opacity: 1;
    color: var(--pm-quote-color);
  }

  &:disabled {
    opacity: 0.3;
    cursor: not-allowed;
  }

  &--danger:hover:not(:disabled) {
    color: #ef4444;
  }
}

// ====== 空状态样式 ======
.pm-empty-state {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 40px;
  color: var(--pm-text-secondary);

  .empty-icon {
    width: 64px;
    height: 64px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 16px;

    i {
      font-size: 28px;
      opacity: 0.4;
    }
  }

  .empty-text {
    font-size: 16px;
    font-weight: 600;
    opacity: 0.7;
  }

  .empty-hint {
    font-size: 12px;
    opacity: 0.5;
  }

  .empty-action {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 8px;
    padding: 8px 16px;
    background: var(--pm-quote-color);
    border: none;
    border-radius: 8px;
    color: var(--pm-panel-bg);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;

    &:hover {
      filter: brightness(1.1);
      transform: translateY(-1px);
    }

    &:active {
      transform: translateY(0);
    }
  }
}

// ============================================================
// 8. 分类样式（与世界书工坊一致的卡片容器设计）
// ============================================================

// 分类卡片容器 - 毛玻璃设计
.category-group {
  display: flex;
  flex-direction: column;
  margin-bottom: 8px;
  padding: 10px 12px;
  background: var(--pm-glass-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--pm-border);
  border-radius: 12px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -1px 0 rgba(0, 0, 0, 0.1);
  position: relative;

  // 悬浮效果 - 边框变为主题色
  &:hover {
    border-color: var(--pm-quote-color);
    box-shadow:
      0 8px 24px rgba(0, 0, 0, 0.18),
      0 0 0 1px var(--pm-quote-color),
      inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  // 分类正在被拖拽
  &--dragging {
    opacity: 0.5;
    border-style: dashed;
  }

  // 分类是拖放目标（条目拖入）
  &--drop-target {
    border-color: var(--pm-quote-color);
    background: var(--pm-hover-bg);
    box-shadow:
      0 0 0 2px rgba(255, 255, 255, 0.1),
      inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  // 拖拽落点指示线
  &--drop-before::before {
    content: '';
    position: absolute;
    top: -2px;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--pm-quote-color);
    border-radius: 2px;
    box-shadow: 0 0 8px var(--pm-quote-color);
    z-index: 10;
  }

  &--drop-after::after {
    content: '';
    position: absolute;
    bottom: -6px;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--pm-quote-color);
    border-radius: 2px;
    box-shadow: 0 0 8px var(--pm-quote-color);
    z-index: 10;
  }

  // 折叠状态
  &--collapsed {
    .category-header__toggle i {
      color: var(--pm-text-secondary);
      opacity: 0.5;
    }
  }
}

// 分类头部
.category-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  cursor: pointer;
  border-radius: 8px;
  transition: background 0.2s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.05);
  }

  // 折叠图标
  &__toggle {
    width: 18px;
    height: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;

    i {
      font-size: 10px;
      color: var(--pm-text-secondary);
      transition: transform 0.2s ease;
    }
  }

  // 文件夹图标 - 酒馆便签风格的方形图标
  &__icon {
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: var(--pm-quote-color);
    border-radius: 7px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);

    i {
      font-size: 12px;
      color: var(--pm-panel-bg);
    }
  }

  // 分类名称
  &__name {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 600;
    font-size: 13px;
    color: var(--pm-text-primary);
  }

  // 编辑输入框
  &__input {
    width: 100%;
    padding: 4px 8px;
    border: 1px solid var(--pm-quote-color);
    border-radius: 4px;
    background: rgba(0, 0, 0, 0.2);
    color: var(--pm-text-primary);
    font-size: 13px;
    outline: none;

    &:focus {
      box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.1);
    }
  }

  // 条目数量 - 简洁胶囊样式
  &__count {
    display: flex;
    align-items: center;
    padding: 4px 10px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    font-size: 12px;
    font-weight: 600;
    color: var(--pm-quote-color);
    flex-shrink: 0;
  }

  // 操作按钮容器
  &__actions {
    display: flex;
    gap: 4px;
    opacity: 0;
    transition: opacity 0.2s ease;
  }

  &:hover &__actions {
    opacity: 1;
  }
}

// 分类操作按钮 - 使用公共 mixin
.category-action {
  @include pm-icon-button;

  &--danger {
    @include pm-icon-button-danger;
  }
}

// 分类内容
.category-content {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 40px;

  // 空状态提示
  &__empty {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 12px;
    color: var(--pm-text-secondary);
    font-size: 12px;
    opacity: 0.6;
    border: 1px dashed rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.02);
  }
}
