    transform: scale(0.99);
  }

  // 展开状态 - 底部圆角去掉，与编辑器连接
  &--expanded {
    border-radius: 10px 10px 0 0;
    border-bottom-color: transparent;
    transform: none !important;
    cursor: default;
    pointer-events: none; // 禁用卡片自身的命中测试，防止背景触发 hover

    & > * {
      pointer-events: auto; // 恢复子元素的交互
    }

    &::before {
      height: 50%;
      background: var(--pm-accent);
    }

    // 展开状态下抑制所有子元素的 hover 效果
    &:hover {
      transform: none !important;
      box-shadow: none !important;
    }
  }

  &--disabled {
    opacity: 0.5;

    .prompt-card__name {
      text-decoration: line-through;
      opacity: 0.7;
    }
  }

  &--dragging {
    opacity: 0.5;
    border-style: dashed;
    cursor: grabbing;
  }

  // 拖拽落点指示线 - 使用公共 mixin
  &--drop-before {
    @include pm-drop-indicator('before');
  }

  &--drop-after {
    @include pm-drop-indicator('after');
  }

  &--placeholder {
    background: transparent;
    border-style: dashed;
    border-color: var(--pm-border);
    opacity: 0.6;
    cursor: default;

    &::before {
      display: none;
    }

    .prompt-card__role {
      background: transparent;
      border-color: var(--pm-border);

      i {
        color: var(--pm-text-secondary);
      }
    }
  }

  // 系统提示词 - 不再默认显示左侧装饰条
  &--system {
    // 左侧装饰条仅在 hover 或高亮时显示
  }

  // 高亮状态 - 搜索匹配时（使用公共动画）
  &--highlighted {
    border-color: var(--pm-accent) !important;
    box-shadow:
      0 0 0 2px rgba(74, 158, 255, 0.3),
      0 4px 16px rgba(74, 158, 255, 0.2) !important;
    animation: pm-highlight-pulse 1.5s ease-in-out;

    &::before {
      height: 70%;
      background: var(--pm-accent);
    }
  }

  &__role {
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0.02) 100%);
    border-radius: 8px;
    flex-shrink: 0;
    border: 1px solid rgba(255, 255, 255, 0.08);
    transition: all 0.2s ease;

    i {
      font-size: 12px;
      color: var(--pm-quote-color);
      transition: all 0.2s ease;
    }
  }

  &:hover:not(.prompt-card--expanded) &__role {
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0.04) 100%);
    border-color: rgba(255, 255, 255, 0.12);

    i {
      color: var(--pm-accent);
    }
  }

  &__name {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--pm-text-primary);
    font-weight: 500;
    font-size: 13px;
    letter-spacing: 0.01em;
  }

  &__position {
    font-size: 10px;
    color: var(--pm-text-secondary);
    background: rgba(255, 255, 255, 0.04);
    padding: 3px 8px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.06);
  }

  // 已收藏图标（独立于 actions，常显）
  &__favorite-icon {
    width: 26px;
    height: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(251, 191, 36, 0.1);
    border: 1px solid rgba(251, 191, 36, 0.2);
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    flex-shrink: 0;

    i {
      font-size: 10px;
      color: #fbbf24;
    }

    &:hover {
      background: rgba(251, 191, 36, 0.15);
      border-color: rgba(251, 191, 36, 0.3);
      transform: translateY(-1px);
    }

    &:active {
      transform: scale(0.95);
    }
  }

  &__actions {
    display: flex;
    gap: 4px;
    opacity: 0;
    transition: opacity 0.2s ease;
  }

  &:hover:not(.prompt-card--expanded) &__actions {
    opacity: 1;
  }

  &__action {
    @include pm-icon-button;

    &--danger {
      @include pm-icon-button-danger;
    }

    // 收藏按钮样式
    &--favorite {
      @include pm-icon-button-favorite;
    }

    // 框选分组按钮样式 - 与其他按钮保持一致
    &--range {
      // 默认状态与其他按钮一致，不设置特殊背景色
    }

    // 框选分组起点按钮样式（已选中状态）- 使用分组头部图标的颜色
    &--range-start {
      background: var(--pm-quote-color);
      border-color: var(--pm-quote-color);

      i {
        color: var(--pm-panel-bg);
        opacity: 1;
      }

      &:hover {
        background: var(--pm-quote-color);
        border-color: var(--pm-quote-color);
        filter: brightness(1.1);
        transform: translateY(-1px);

        i {
          color: var(--pm-panel-bg);
        }
      }
    }

    // 已收藏状态
    &--favorited {
      i {
        color: #fbbf24 !important;
        opacity: 1 !important;
      }

      &:hover {
        background: rgba(251, 191, 36, 0.15);
        border-color: rgba(251, 191, 36, 0.3);
      }
    }
  }

  &__toggle {
    cursor: pointer;
    padding: 4px;
    font-size: 1.1em;
    flex-shrink: 0;
    transition: all 0.2s ease;

    .fa-toggle-on {
      color: var(--pm-accent);
    }

    .fa-toggle-off {
      color: var(--pm-text-secondary);
      opacity: 0.6;
    }

    &:hover:not(.prompt-card--expanded) {
      transform: scale(1.1);

      .fa-toggle-off {
        opacity: 1;
        color: var(--pm-text-primary);
      }
    }
  }

  // ============ 比对状态边框样式 ============

  // 红框 - name相同content不同
  &--diff-content {
    border-color: rgba(239, 68, 68, 0.5) !important;
    box-shadow:
      0 0 0 1px rgba(239, 68, 68, 0.3),
      0 2px 8px rgba(239, 68, 68, 0.15);

    &::before {
      background: #ef4444;
      height: 60%;
    }
  }

  // 绿框 - name不同content相同
  &--diff-name {
    border-color: rgba(34, 197, 94, 0.5) !important;
    box-shadow:
      0 0 0 1px rgba(34, 197, 94, 0.3),
      0 2px 8px rgba(34, 197, 94, 0.15);

    &::before {
      background: #22c55e;
      height: 60%;
    }
  }

  // 金框 - 正文相似
  &--diff-partial {
    border-color: rgba(234, 179, 8, 0.5) !important;
    box-shadow:
      0 0 0 1px rgba(234, 179, 8, 0.3),
      0 2px 8px rgba(234, 179, 8, 0.15);

    &::before {
      background: #eab308;
      height: 60%;
    }
  }

  // 蓝框 - 单侧存在
  &--diff-unique {
    border-color: rgba(59, 130, 246, 0.5) !important;
    box-shadow:
      0 0 0 1px rgba(59, 130, 246, 0.3),
      0 2px 8px rgba(59, 130, 246, 0.15);

    &::before {
      background: #3b82f6;
      height: 60%;
    }
  }
}

