    align-items: center;
    justify-content: center;
    padding: 12px;
    color: var(--pm-text-secondary);
    font-size: 12px;
    opacity: 0.6;
    border: 1px dashed rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.02);
  }
}
