    padding: 12px 1rem;
    background: var(--pm-bar-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--pm-border);
    flex-shrink: 0;
    flex-wrap: wrap;
  }

  &__content {
    flex: 1;
    min-height: 0;
    padding: 16px;
    display: flex;
    flex-direction: column;
    background: var(--pm-glass-bg);
  }

  &__textarea {
    flex: 1;
    width: 100%;
    padding: 16px;
    background: var(--pm-card-bg);
    border: 1px solid var(--pm-border);
    border-radius: 12px;
    color: var(--pm-text-primary);
    font-size: 14px;
    line-height: 1.6;
    resize: none;
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    transition: all 0.2s ease;
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.06),
      inset 0 -1px 0 rgba(0, 0, 0, 0.03);

    // 使用公共滚动条样式
    @include pm-scrollbar(6px);

    &::placeholder {
      color: var(--pm-text-secondary);
      opacity: 0.5;
    }

    &:hover {
      border-color: rgba(255, 255, 255, 0.15);
    }

    &:focus {
      outline: none;
      border-color: var(--pm-quote-color);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.08),
        0 0 0 1px rgba(255, 255, 255, 0.05);
    }
  }
}

// 设置项 - 使用卡片风格
.setting-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0.35rem 0.5rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);

  &:hover {
    background: rgba(255, 255, 255, 0.06);
    border-color: rgba(255, 255, 255, 0.12);
  }

  &--toggle {
    margin-left: auto;
  }

  &--info {
    margin-left: 8px;
    background: transparent;
    border-color: transparent;

    &:hover {
      background: transparent;
      border-color: transparent;
    }
  }
}

.setting-label {
  font-size: 12px;
  color: var(--pm-text-secondary);
  white-space: nowrap;
}

.setting-select {
  @include pm-select(auto, 12px);
  padding: 4px 8px;
  border-radius: 6px;
}

.setting-input {
  @include pm-input-base(auto, 12px);
  @include pm-number-input(50px);
  padding: 4px 8px;
  border-radius: 6px;
}

.toggle-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  font-size: 1.3em;
  color: var(--pm-text-secondary);
  transition: all 0.2s ease;

  &--active {
    color: var(--pm-quote-color);
  }

  &:hover {
    transform: scale(1.1);
  }
}

.char-count {
  font-size: 11px;
  color: var(--pm-text-secondary);
  opacity: 0.7;
}
