// 分类卡片容器 - 毛玻璃设计
.category-group {
  display: flex;
  flex-direction: column;
  margin-bottom: 8px;
  padding: 10px 12px;
  background: var(--pm-glass-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--pm-border);
  border-radius: 12px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -1px 0 rgba(0, 0, 0, 0.1);
  position: relative;

  // 悬浮效果 - 边框变为主题色
  &:hover {
    border-color: var(--pm-quote-color);
    box-shadow:
      0 8px 24px rgba(0, 0, 0, 0.18),
      0 0 0 1px var(--pm-quote-color),
      inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  // 分类正在被拖拽
  &--dragging {
    opacity: 0.5;
    border-style: dashed;
  }

  // 分类是拖放目标（条目拖入）
  &--drop-target {
    border-color: var(--pm-quote-color);
    background: var(--pm-hover-bg);
    box-shadow:
      0 0 0 2px rgba(255, 255, 255, 0.1),
      inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  // 拖拽落点指示线
  &--drop-before::before {
    content: '';
    position: absolute;
    top: -2px;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--pm-quote-color);
    border-radius: 2px;
    box-shadow: 0 0 8px var(--pm-quote-color);
    z-index: 10;
  }

  &--drop-after::after {
    content: '';
    position: absolute;
    bottom: -6px;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--pm-quote-color);
    border-radius: 2px;
    box-shadow: 0 0 8px var(--pm-quote-color);
    z-index: 10;
  }

  // 折叠状态
  &--collapsed {
    .category-header__toggle i {
      color: var(--pm-text-secondary);
      opacity: 0.5;
    }
  }
}

// 分类头部
.category-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  cursor: pointer;
  border-radius: 8px;
  transition: background 0.2s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.05);
  }

  // 折叠图标
