    flex-shrink: 0;

    i {
      font-size: 10px;
      color: var(--pm-text-secondary);
      transition: transform 0.2s ease;
    }
  }

  // 文件夹图标 - 酒馆便签风格的方形图标
  &__icon {
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: var(--pm-quote-color);
    border-radius: 7px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);

    i {
      font-size: 12px;
      color: var(--pm-panel-bg);
    }
  }

  // 分类名称
  &__name {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 600;
    font-size: 13px;
    color: var(--pm-text-primary);
  }

  // 编辑输入框
  &__input {
    width: 100%;
    padding: 4px 8px;
    border: 1px solid var(--pm-quote-color);
    border-radius: 4px;
    background: rgba(0, 0, 0, 0.2);
    color: var(--pm-text-primary);
    font-size: 13px;
    outline: none;

    &:focus {
      box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.1);
