      font-size: 12px;
      opacity: 0.4;
      margin: 0;
    }
  }
}

// 提示词条目容器
.prompt-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  &__main {
    display: flex;
    flex-direction: row;
    align-items: flex-start;
    width: 100%;
  }

  // 有比对状态时显示比对图标
  &--has-diff {
    .prompt-item__diff-label {
      display: flex;
    }
  }

  // 多选模式下的布局
  &--multi-select {
    .prompt-item__checkbox {
      display: flex;
    }
  }

  // 比对状态图标（默认隐藏）
  &__diff-label {
    display: none;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    flex-shrink: 0;
    font-size: 10px;
    font-weight: 600;
    border-radius: 4px;
    margin-right: 6px;
    margin-top: 9px;
    transition: all 0.2s ease;

    i {
      font-size: 8px;
    }

    // 红色 - name相同content不同
    &--content {
      background: rgba(239, 68, 68, 0.15);
      color: #ef4444;
      border: 1px solid rgba(239, 68, 68, 0.3);
    }

    // 绿色 - name不同content相同
    &--name {
      background: rgba(34, 197, 94, 0.15);
      color: #22c55e;
      border: 1px solid rgba(34, 197, 94, 0.3);
    }

    // 金色 - 正文相似
    &--partial {
      background: rgba(234, 179, 8, 0.15);
      color: #eab308;
      border: 1px solid rgba(234, 179, 8, 0.3);
    }

    // 蓝色 - 单侧存在
    &--unique {
      background: rgba(59, 130, 246, 0.15);
      color: #3b82f6;
      border: 1px solid rgba(59, 130, 246, 0.3);
    }

    // 可点击状态
    &--clickable {
      cursor: pointer;

      &:hover {
        transform: scale(1.1);
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
      }

      &:active {
        transform: scale(0.95);
      }
    }
  }

  // 非多选模式时隐藏复选框
  &__checkbox {
    display: none;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 36px;
    flex-shrink: 0;
    cursor: pointer;
    transition: all 0.2s ease;

    i {
      font-size: 16px;
      color: var(--pm-text-secondary);
      opacity: 0.6;
      transition: all 0.2s ease;
    }

    &:hover i {
      opacity: 1;
      color: var(--pm-quote-color);
    }

    // 选中状态
    .fa-square-check {
      color: var(--pm-quote-color);
      opacity: 1;
    }
  }

  // 卡片容器需要占满剩余空间
  :deep(.prompt-card) {
    flex: 1;
    min-width: 0;
  }

  // 展开状态 - 卡片和编辑器融为一体
  &--expanded {
    background: var(--pm-card-bg);
    border-radius: 10px;
    border: 1px solid var(--pm-border);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
    // 移除 overflow: hidden，避免内容被意外隐藏

    // 多选模式下展开时的布局调整
    &.prompt-item--multi-select {
      width: calc(100% - 28px);
      margin-left: 28px;
      position: relative;

      .prompt-item__main > .prompt-item__checkbox {
        position: absolute;
        left: -28px;
        top: 8px;
      }
    }

    // 卡片在展开状态下去掉自己的边框和圆角
    :deep(.prompt-card) {
      border: none;
      border-radius: 10px 10px 0 0;
      background: transparent !important;
      box-shadow: none !important;
      flex: 1;
      width: 100%;

      &::before {
        left: -1px;
      }
    }
  }
}

// 内联编辑器容器 - 使用 Grid 技巧实现平滑高度过渡
.inline-editor-container {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  width: 100%;
  overflow: hidden;

  &--expanded {
    grid-template-rows: 1fr;
  }
}

.inline-editor-inner {
  min-height: 0;
  background: transparent;
}

// 编辑器淡入淡出动画 - 配合 Grid 技巧实现平滑收起
.editor-fade-enter-active,
.editor-fade-leave-active {
  transition: opacity 0.3s ease;
}

.editor-fade-enter-from,
.editor-fade-leave-to {
  opacity: 0;
}

