    outline: none;

    &:focus {
      box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.1);
    }
  }

  // 条目数量 - 简洁胶囊样式
  &__count {
    display: flex;
    align-items: center;
    padding: 4px 10px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    font-size: 12px;
    font-weight: 600;
    color: var(--pm-quote-color);
    flex-shrink: 0;
  }

  // 操作按钮容器
  &__actions {
    display: flex;
    gap: 4px;
    opacity: 0;
    transition: opacity 0.2s ease;
  }

  &:hover &__actions {
    opacity: 1;
  }
}

// 分类操作按钮 - 使用公共 mixin
.category-action {
  @include pm-icon-button;

  &--danger {
    @include pm-icon-button-danger;
  }
}

// 分类内容
.category-content {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-height: 40px;

  // 空状态提示
  &__empty {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 12px;
    color: var(--pm-text-secondary);
    font-size: 12px;
    opacity: 0.6;
    border: 1px dashed rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.02);
  }
}

// ============ 分割线分组卡片样式 - 与世界书工坊保持一致 ============

// 分组卡片容器 - 毛玻璃设计
.section-group {
  display: flex;
  flex-direction: column;
  margin-bottom: 2px;
  padding: 10px 12px;
  background: var(--pm-glass-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--pm-border);
  border-radius: 12px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -1px 0 rgba(0, 0, 0, 0.1);
  position: relative;

  // 悬浮效果 - 边框变为主题色
  &:hover {
    border-color: var(--pm-quote-color);
    box-shadow:
      0 8px 24px rgba(0, 0, 0, 0.18),
      0 0 0 1px var(--pm-quote-color),
      inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }

  // 一键禁用状态
  &--disabled {
    opacity: 0.6;

    :deep(.section-header__icon) {
      background: #ef4444;
    }
  }

  // 折叠状态
  &--collapsed {
    :deep(.section-header__toggle i) {
      color: var(--pm-text-secondary);
      opacity: 0.5;
    }
  }

  // 拖放指示线 - 上边缘（通过 Vue class 绑定触发）
  &--drop-before::before {
    content: '';
    position: absolute;
    top: -4px;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--pm-quote-color);
    border-radius: 2px;
    box-shadow: 0 0 8px var(--pm-quote-color);
    z-index: 10;
  }

  // 拖放指示线 - 下边缘（通过 Vue class 绑定触发）
  &--drop-after::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--pm-quote-color);
    border-radius: 2px;
    box-shadow: 0 0 8px var(--pm-quote-color);
    z-index: 10;
  }

  // 拖放到中间区域 - 高亮整个分组卡片（通过 Vue class 绑定触发）
  &--drop-into {
    background: rgba(var(--pm-quote-color-rgb, 99, 102, 241), 0.15);
    border-color: var(--pm-quote-color);
    box-shadow:
      0 8px 24px rgba(0, 0, 0, 0.2),
      0 0 0 2px var(--pm-quote-color),
      0 0 16px rgba(var(--pm-quote-color-rgb, 99, 102, 241), 0.15),
      inset 0 1px 0 rgba(255, 255, 255, 0.1);
  }

  // 分组头部在卡片内部时，去掉自身的背景和边框
  :deep(.section-header) {
    background: transparent;
    border: none;
    box-shadow: none;
    padding: 4px 6px;
    min-height: auto;
    margin: 0;
    border-radius: 8px;
  }

  // 禁用 SectionHeader 自身的拖放指示线（已转移到卡片容器）
  :deep(.section-header--drop-before),
  :deep(.section-header--drop-after) {
    box-shadow: none !important;
  }

  // 禁用 SectionHeader 自身的拖放高亮效果（已转移到卡片容器）
  :deep(.section-header--drop-into) {
    background: transparent !important;
    border: none !important;
    transform: none !important;
    box-shadow: none !important;
  }

  :deep(.section-header:hover) {
    background: rgba(255, 255, 255, 0.05);
    transform: none;
  }
}

// 分组内容区域
.section-content {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-height: 40px;

  // 空状态提示
  &__empty {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 12px;
    color: var(--pm-text-secondary);
    font-size: 12px;
    opacity: 0.6;
    border: 1px dashed rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.02);
  }
}

// 框选分组起点条目样式
.prompt-item--range-start {
  position: relative;

  // 起点条目的特殊边框样式
  :deep(.prompt-card) {
    border-left: 3px solid #22c55e;
    background: rgba(34, 197, 94, 0.05);

    &:hover {
      background: rgba(34, 197, 94, 0.08);
    }
  }
}
