  switch (status) {
    case 'content':
      return '内容不同';
    case 'name':
      return '已改名';
    case 'partial':
      return '正文相似';
    case 'unique':
      return leftId && !rightId ? '仅上侧预设存在' : '仅下侧预设存在';
    case 'match':
      return '一致';
    default:
      return '';
