;(() => {
  const PMM_ID = 'pm-standalone-mobile-v1';
  const isMobile = () => {
    try { return Math.min(window.innerWidth || 9999, (window.parent && window.parent.innerWidth) || 9999) <= 768; }
    catch (_) { return (window.innerWidth || 9999) <= 768; }
  };

  const parentDoc = (() => {
