    } catch (_) {
      return document;
    }
  })();

  const docs = parentDoc === document ? [document] : [document, parentDoc];

  const CSS = `
/* 桌面 / 手机共用：防止酒馆美化隐藏悬浮面板左侧的“打开编辑面板”。 */
#preset-manager-floating-panel .panel-header > .panel-action[title="打开编辑面板"] {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  flex: 0 0 26px !important;
  width: 26px !important;
  min-width: 26px !important;
  max-width: 26px !important;
  height: 26px !important;
  align-items: center !important;
  justify-content: center !important;
  overflow: visible !important;
  clip: auto !important;
  clip-path: none !important;
  transform: none !important;
  pointer-events: auto !important;
}

#preset-manager-floating-panel .panel-header > .panel-action[title="打开编辑面板"] > i {
  display: inline-block !important;
  visibility: visible !important;
  opacity: .85 !important;
  width: auto !important;
  height: auto !important;
  overflow: visible !important;
  clip: auto !important;
  clip-path: none !important;
  transform: none !important;
}

#preset-manager-floating-panel .panel-header > .panel-action[title="打开编辑面板"] > i::before {
  content: "\f044" !important;
  display: inline-block !important;
  font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", FontAwesome !important;
  font-weight: 900 !important;
}

#preset-manager-floating-panel .panel-header > .panel-action[title="打开编辑面板"] + .panel-divider {
  display: block !important;
  visibility: visible !important;
  opacity: .4 !important;
  flex: 0 0 1px !important;
  width: 1px !important;
  min-width: 1px !important;
  height: 18px !important;
  overflow: visible !important;
  clip: auto !important;
  clip-path: none !important;
  transform: none !important;
}

@media screen and (max-width: 768px) {
  :root {
    --pmm-safe-top: max(env(safe-area-inset-top, 0px), 8px);
    --pmm-safe-bottom: max(env(safe-area-inset-bottom, 0px), 22px);
    --pmm-gap: 6px;
    --pmm-toolbar-h: 40px;
  }

  /* ===== 0. 手机入口 / 桌面浮动面板 ===== */
  #preset-manager-floating-panel {
    display: none !important;
    visibility: hidden !important;
    pointer-events: none !important;
  }

  #pm-mobile-fab-standalone {
    position: fixed !important;
    left: 14px;
    top: calc(var(--pmm-safe-top) + 8px);
    width: 46px !important;
    height: 46px !important;
    border: 1px solid rgba(255,255,255,.18) !important;
    border-radius: 50% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: var(--SmartThemeQuoteColor, #8b7b7b) !important;
    color: #fff !important;
    box-shadow: 0 8px 24px rgba(0,0,0,.30) !important;
    z-index: 2147483000 !important;
    padding: 0 !important;
    opacity: .92 !important;
    -webkit-tap-highlight-color: transparent !important;
    touch-action: none !important;
    pointer-events: auto !important;
    isolation: isolate !important;
    user-select: none !important;
    -webkit-user-select: none !important;
    cursor: grab !important;
    transition: left .22s ease, top .22s ease, transform .22s ease, opacity .22s ease, box-shadow .22s ease !important;
    will-change: left, top, transform !important;
  }

  #pm-mobile-fab-standalone i {
    font-size: 18px !important;
    pointer-events: none !important;
  }

  #pm-mobile-fab-standalone.pmm-fab-dragging {
    cursor: grabbing !important;
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
    box-shadow: 0 10px 28px rgba(0,0,0,.38) !important;
  }

  #pm-mobile-fab-standalone.pmm-fab-snap-left {
    transform: translateX(-29px) !important;
    opacity: .24 !important;
    box-shadow: 0 4px 14px rgba(0,0,0,.12) !important;
  }

  #pm-mobile-fab-standalone.pmm-fab-snap-right {
    transform: translateX(29px) !important;
    opacity: .24 !important;
    box-shadow: 0 4px 14px rgba(0,0,0,.12) !important;
  }


  /* 1.3.11：主面板根节点强制占据顶层 viewport。
     解决脚本 iframe 中只出现一小块黑色遮罩、真正面板被裁掉的问题。 */
  #preset-manager-main-panel {
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100dvh !important;
    min-height: 100vh !important;
    z-index: 2147482000 !important;
    pointer-events: auto !important;
    overflow: visible !important;
    isolation: isolate !important;
    transform: none !important;
    filter: none !important;
    perspective: none !important;
    contain: none !important;
  }

  #preset-manager-main-panel > .pm-overlay,
  #preset-manager-main-panel .pm-overlay {
    position: absolute !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    z-index: 1 !important;
  }


  /* 1.3.17：所有二级窗口都留在 #preset-manager-main-panel 这一棵 DOM 内。
     主 root 自己已经在顶层，因此内部只需要正常的局部层级。 */
  [data-pmm-diff-detail="1"] {
    position: fixed !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    z-index: 12000 !important;
    pointer-events: auto !important;
  }

  .pmm-content-diff-overlay {
    z-index: 12100 !important;
    pointer-events: auto !important;
  }

  #pmrx-preset-regex-transfer-overlay {
    z-index: 12200 !important;
    pointer-events: auto !important;
  }


  /* 1.3.18：比对详情是真正直属主 root 的全屏 portal。 */
  #pmm-diff-detail-portal {
    position: fixed !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
    z-index: 12000 !important;
    box-sizing: border-box !important;
    padding: 8px 7px calc(var(--pmm-safe-bottom) + 56px) !important;
    display: flex !important;
    align-items: stretch !important;
    justify-content: stretch !important;
    overflow: hidden !important;
    pointer-events: auto !important;
  }

  #pmm-diff-detail-portal > [data-pmm-diff-portal-modal="1"] {
    flex: 1 1 auto !important;
    width: 100% !important;
    height: auto !important;
    max-width: none !important;
    max-height: 100% !important;
    min-height: 0 !important;
    margin: 0 !important;
    display: flex !important;
    flex-direction: column !important;
