`;

  function injectStyle(doc) {
    if (!doc || !doc.head || doc.getElementById(PMM_ID)) return;
    const s = doc.createElement('style');
    s.id = PMM_ID;
    s.textContent = CSS;
    doc.head.appendChild(s);
  }

  docs.forEach(injectStyle);

  /* 每次脚本运行都有独立标记：用于识别刷新后遗留的旧悬浮按钮。 */
  const FAB_RUNTIME_TOKEN = Symbol('pmm-mobile-fab-runtime');
  try { parentDoc.__pmmFabActiveRuntimeToken = FAB_RUNTIME_TOKEN; } catch (_) {}

  function fabRuntimeIsCurrent() {
    try { return parentDoc.__pmmFabActiveRuntimeToken === FAB_RUNTIME_TOKEN; }
    catch (_) { return true; }
  }
  const FAB_VISIBILITY_KEY = 'pmm_mobile_fab_visible_v1';

  function fabIsEnabled() {
    try {
      const storage = parentDoc?.defaultView?.localStorage || window.localStorage;
      return storage.getItem(FAB_VISIBILITY_KEY) !== '0';
    } catch (_) {
      return true;
    }
  }

  function saveFabEnabled(enabled) {
    try {
      const storage = parentDoc?.defaultView?.localStorage || window.localStorage;
      storage.setItem(FAB_VISIBILITY_KEY, enabled ? '1' : '0');
    } catch (_) {}
  }

  function removeFab(doc) {
    try {
      const button = doc?.getElementById?.('pm-mobile-fab-standalone');
      if (!button) return;
      try { button.__pmmFabCleanup?.(); } catch (_) {}
      button.remove();
    } catch (_) {}
  }

  function setFabEnabled(enabled, notify = true) {
    saveFabEnabled(enabled);
    docs.forEach(doc => {
      if (!doc) return;
      if (enabled) makeFab(doc);
      else removeFab(doc);
    });
    docs.forEach(doc => ensureWorkshopControls(doc));
    if (notify) {
      try {
        const toast = (typeof toastr !== 'undefined') ? toastr : window.parent?.toastr;
        toast?.info?.(enabled ? '悬浮按钮已显示' : '悬浮按钮已隐藏');
      } catch (_) {}
    }
  }

  function workshopPanelVisible() {
    try {
      const roots = [...new Set([parentDoc, document, ...docs].filter(Boolean))];
      return roots.some(root => Array.from(root.querySelectorAll?.('#preset-manager-main-panel') || []).some(panel => {
        if (!panel?.isConnected) return false;
        const panelWin = panel.ownerDocument?.defaultView || window;
        const style = panelWin?.getComputedStyle?.(panel);
        if (style && (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0)) return false;
        const rect = panel.getBoundingClientRect();
        return rect.width > 2 && rect.height > 2 && panel.getClientRects().length > 0;
      }));
    } catch (_) {
      return false;
    }
  }

  function scheduleWorkshopControls() {
    [0, 80, 220, 500, 900].forEach(delay => {
      setTimeout(() => docs.forEach(doc => ensureWorkshopControls(doc)), delay);
    });
  }

  async function openWorkshopFromWand() {
    if (!fabRuntimeIsCurrent()) return false;
    if (workshopPanelVisible()) {
      scheduleWorkshopControls();
      return true;
    }

    try {
      const bridge = parentDoc?.__pmmWorkshopOpenBridge;
      if (bridge?.token === FAB_RUNTIME_TOKEN && typeof bridge.open === 'function') {
        const result = await bridge.open();
        scheduleWorkshopControls();
        return result !== false;
      }
    } catch (_) {}

    let triggered = false;
    try {
      if (typeof fo === 'function') {
        fo();
        triggered = true;
      }
    } catch (error) {
      console.warn('[预设工坊][魔法棒入口] 直接打开失败，尝试事件入口', error);
    }

    if (!triggered) {
      try {
        if (typeof getButtonEvent === 'function' && typeof eventEmit === 'function') {
          const eventName = getButtonEvent('打开预设管家');
          if (eventName) {
            eventEmit(eventName);
            triggered = true;
          }
        }
      } catch (error) {
        console.warn('[预设工坊][魔法棒入口] 事件入口打开失败', error);
      }
    }

    scheduleWorkshopControls();
    if (!triggered) {
      try {
        const toast = (typeof toastr !== 'undefined') ? toastr : window.parent?.toastr;
        toast?.error?.('预设工坊暂时无法打开，请刷新酒馆页面后再试');
      } catch (_) {}
    }
    return triggered;
  }

  function ensureFloatingPanelEditButton(doc) {
    if (!doc) return;
    const buttons = Array.from(doc.querySelectorAll?.(
      '#preset-manager-floating-panel .panel-header > .panel-action[title="打开编辑面板"]'
    ) || []);

    buttons.forEach(button => {
      button.style.setProperty('display', 'flex', 'important');
      button.style.setProperty('visibility', 'visible', 'important');
      button.style.setProperty('opacity', '1', 'important');
      button.style.setProperty('flex', '0 0 26px', 'important');
      button.style.setProperty('width', '26px', 'important');
      button.style.setProperty('min-width', '26px', 'important');
      button.style.setProperty('max-width', '26px', 'important');
      button.style.setProperty('height', '26px', 'important');
      button.style.setProperty('align-items', 'center', 'important');
      button.style.setProperty('justify-content', 'center', 'important');
      button.style.setProperty('overflow', 'visible', 'important');
      button.style.setProperty('clip', 'auto', 'important');
      button.style.setProperty('clip-path', 'none', 'important');
      button.style.setProperty('transform', 'none', 'important');
      button.style.setProperty('pointer-events', 'auto', 'important');

      const icon = button.querySelector('i');
      if (icon) {
        icon.style.setProperty('display', 'inline-block', 'important');
        icon.style.setProperty('visibility', 'visible', 'important');
