  function updateBranchFullscreenButton(button, expanded) {
    if (!button) return;
    const title = expanded ? '退出分支全屏' : '全屏编辑分支';
    button.title = title;
    button.setAttribute('aria-label', title);
    button.setAttribute('aria-pressed', expanded ? 'true' : 'false');
    button.classList.toggle('active', expanded);
    const icon = button.querySelector('i');
    if (icon) icon.className = expanded ? 'fa-solid fa-compress' : 'fa-solid fa-expand';
  }

  function ensureBranchFullscreen(root, doc) {
    if (!root || !doc) return;
    ensureBranchFullscreenStyles(doc);

    const containers = Array.from(root.querySelectorAll?.('.pm-panel-container') || []);
    containers.forEach(container => {
      const isBranchMode = container.classList.contains('pm-panel-container--branch-mode');
      if (!isMobile() || !isBranchMode) {
        container.classList.remove(BRANCH_FULLSCREEN_CLASS);
        Array.from(container.querySelectorAll?.('.' + BRANCH_FULLSCREEN_BUTTON_CLASS) || [])
          .forEach(button => button.remove());
        return;
      }

      const branchPanel = Array.from(container.children)
        .find(child => child.classList?.contains('preset-panel'));
      const headerRight = branchPanel?.querySelector?.('.pm-header .header-right');
      if (!branchPanel || !headerRight) return;

      const staleButtons = Array.from(container.querySelectorAll('.' + BRANCH_FULLSCREEN_BUTTON_CLASS))
        .filter(button => button.__pmmFabRuntimeToken !== FAB_RUNTIME_TOKEN);
      staleButtons.forEach(button => button.remove());

      let button = headerRight.querySelector('.' + BRANCH_FULLSCREEN_BUTTON_CLASS);
      if (!button) {
        button = doc.createElement('button');
        button.type = 'button';
        button.className = 'header-card action-card ' + BRANCH_FULLSCREEN_BUTTON_CLASS;
        button.__pmmFabRuntimeToken = FAB_RUNTIME_TOKEN;
        button.innerHTML = '<div class="card-icon"><i class="fa-solid fa-expand"></i></div>';
        button.addEventListener('click', event => {
          event.preventDefault();
          event.stopPropagation();
          const expanded = container.classList.toggle(BRANCH_FULLSCREEN_CLASS);
          updateBranchFullscreenButton(button, expanded);
        });
        const closeButton = headerRight.querySelector('.close-card');
        headerRight.insertBefore(button, closeButton || null);
      }

      updateBranchFullscreenButton(
        button,
        container.classList.contains(BRANCH_FULLSCREEN_CLASS),
      );
    });
  }

  function ensureWorkshopControls(doc) {
    if (!doc) return;
    const roots = Array.from(doc.querySelectorAll?.('#preset-manager-main-panel') || []);
    roots.forEach(root => {
      ensureBranchFullscreen(root, doc);
      const cards = Array.from(root.querySelectorAll?.('.theme-switch-card') || []);
      cards.forEach(card => {
        const lightButton = card.querySelector('.theme-btn[title="白色模式"]');
        const darkButton = card.querySelector('.theme-btn[title="黑色模式"]');
        const autoButton = card.querySelector('.theme-btn[title="主题模式"]');
        if (!lightButton || !darkButton) return;

        const stale = Array.from(card.querySelectorAll('.pmm-runtime-theme-btn'))
          .filter(button => button.__pmmFabRuntimeToken !== FAB_RUNTIME_TOKEN);
        stale.forEach(button => { try { button.remove(); } catch (_) {} });

        if (!isMobile()) {
          [lightButton, darkButton, autoButton].filter(Boolean).forEach(button => button.style.removeProperty('display'));
          Array.from(card.querySelectorAll('.pmm-runtime-theme-btn')).forEach(button => button.remove());
          return;
        }

        [lightButton, darkButton, autoButton].filter(Boolean).forEach(button => {
          button.style.setProperty('display', 'none', 'important');
        });

        let themeToggle = card.querySelector('.pmm-mobile-theme-toggle');
        if (!themeToggle) {
          themeToggle = doc.createElement('button');
          themeToggle.type = 'button';
          themeToggle.className = 'theme-btn pmm-runtime-theme-btn pmm-mobile-theme-toggle';
          themeToggle.__pmmFabRuntimeToken = FAB_RUNTIME_TOKEN;
          themeToggle.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            const currentlyDark = darkButton.classList.contains('active');
            (currentlyDark ? lightButton : darkButton).click();
            setTimeout(() => ensureWorkshopControls(doc), 0);
            setTimeout(() => ensureWorkshopControls(doc), 80);
          });
          card.appendChild(themeToggle);
        }

        const darkActive = darkButton.classList.contains('active');
        setRuntimeButtonVisual(
          themeToggle,
          darkActive ? 'fa-solid fa-moon' : 'fa-solid fa-sun',
          darkActive ? '切换为白色模式' : '切换为黑色模式',
          true,
        );

        let fabToggle = card.querySelector('.pmm-mobile-fab-toggle');
        if (!fabToggle) {
          fabToggle = doc.createElement('button');
          fabToggle.type = 'button';
          fabToggle.className = 'theme-btn pmm-runtime-theme-btn pmm-mobile-fab-toggle';
          fabToggle.__pmmFabRuntimeToken = FAB_RUNTIME_TOKEN;
          fabToggle.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            setFabEnabled(!fabIsEnabled());
          });
          card.appendChild(fabToggle);
        }

        const enabled = fabIsEnabled();
        setFabSwitchVisual(fabToggle, enabled);
      });
    });
  }

  function makeFab(doc) {
    if (!isMobile() || !doc || !doc.body || !fabRuntimeIsCurrent() || !fabIsEnabled()) return;

    /*
     * 安卓 WebView / iOS Safari 在刷新、热重载或后台恢复后，可能保留旧 DOM，
     * 但旧按钮闭包中的 fo()、事件桥和 iframe window 已经失效。
     * 同一次运行的重复扫描继续复用；跨运行残留则先清理再重建并重新绑事件。
     */
    const existing = doc.getElementById('pm-mobile-fab-standalone');
    if (existing) {
      if (existing.__pmmFabRuntimeToken === FAB_RUNTIME_TOKEN && existing.isConnected) return;
      try { existing.__pmmFabCleanup?.(); } catch (_) {}
      try { existing.remove(); } catch (_) {
        try { existing.parentNode?.removeChild(existing); } catch (_) {}
      }
    }

    const win = doc.defaultView || window;
    const STORAGE_KEY = 'pmm_fab_position_v1';
    const SIZE = 46;
    const EDGE_TRIGGER = 42;
    const SIDE_MARGIN = 6;

    const b = doc.createElement('button');
    b.id = 'pm-mobile-fab-standalone';
    b.__pmmFabRuntimeToken = FAB_RUNTIME_TOKEN;
    b.type = 'button';
    b.title = '预设管理';
    b.setAttribute('aria-label', '预设管理');
    b.innerHTML = '<i class="fa-solid fa-sliders"></i>';
    doc.body.appendChild(b);

    let x = Math.max(SIDE_MARGIN, (win.innerWidth || 390) - SIZE - 14);
    let y = 34;
    let snap = '';
    let dragging = false;
    let moved = false;
    let suppressClick = false;
    let pointerId = null;
    let startClientX = 0;
    let startClientY = 0;
    let startX = 0;
    let startY = 0;

    function viewport() {
      return {
        w: Math.max(1, win.innerWidth || doc.documentElement.clientWidth || 390),
        h: Math.max(1, win.innerHeight || doc.documentElement.clientHeight || 844)
      };
    }

    function clampPosition(px, py) {
      const vp = viewport();
      return {
        x: Math.max(SIDE_MARGIN, Math.min(px, vp.w - SIZE - SIDE_MARGIN)),
        y: Math.max(8, Math.min(py, vp.h - SIZE - 18))
      };
    }

    function clearSnapClass() {
      b.classList.remove('pmm-fab-snap-left', 'pmm-fab-snap-right');
    }

    function applyPosition() {
      clearSnapClass();
      b.style.left = Math.round(x) + 'px';
      b.style.top = Math.round(y) + 'px';
      b.style.right = 'auto';

      if (snap === 'left') b.classList.add('pmm-fab-snap-left');
      if (snap === 'right') b.classList.add('pmm-fab-snap-right');
    }

    function save() {
      try {
        win.localStorage.setItem(STORAGE_KEY, JSON.stringify({
          x: Math.round(x),
          y: Math.round(y),
          snap: snap || ''
        }));
      } catch (_) {}
    }

    function restore() {
      try {
        const raw = win.localStorage.getItem(STORAGE_KEY);
        if (!raw) return;
        const pos = JSON.parse(raw);
        if (!pos || typeof pos !== 'object') return;

        const p = clampPosition(
          Number.isFinite(Number(pos.x)) ? Number(pos.x) : x,
          Number.isFinite(Number(pos.y)) ? Number(pos.y) : y
        );
        x = p.x;
        y = p.y;
        snap = (pos.snap === 'left' || pos.snap === 'right') ? pos.snap : '';
      } catch (_) {}
    }

    function settleToEdge() {
      const vp = viewport();
      const center = x + SIZE / 2;

      if (center <= EDGE_TRIGGER + SIZE / 2) {
        snap = 'left';
        x = SIDE_MARGIN;
      } else if ((vp.w - center) <= EDGE_TRIGGER + SIZE / 2) {
        snap = 'right';
        x = vp.w - SIZE - SIDE_MARGIN;
      } else {
        snap = '';
      }

      const p = clampPosition(x, y);
      x = p.x;
      y = p.y;
      applyPosition();
      save();
    }

    function getMainPanelCandidates() {
      try {
        const roots = [...new Set([parentDoc, doc, document].filter(Boolean))];
        const candidates = roots.flatMap(root =>
          Array.from(root.querySelectorAll?.('#preset-manager-main-panel') || [])
        );
        return [...new Set(candidates)].filter(panel => panel?.isConnected);
      } catch (_) {
        return [];
      }
    }

    function panelIsVisible(panel) {
      try {
        if (!panel?.isConnected || panel.getAttribute?.('aria-hidden') === 'true') return false;
        const panelWin = panel.ownerDocument?.defaultView || win;
        const style = panelWin?.getComputedStyle?.(panel);
        if (style && (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0)) {
          return false;
        }
        const rect = panel.getBoundingClientRect();
        return rect.width > 2 && rect.height > 2 && panel.getClientRects().length > 0;
      } catch (_) {
        return false;
      }
    }

    function chooseMainPanel() {
      const candidates = getMainPanelCandidates();
      return candidates.find(panelIsVisible)
        || candidates.find(panel => panel.childElementCount > 0)
        || candidates[0]
        || null;
    }

    function ensureMainPanelInTopDocument() {
      try {
        const panel = chooseMainPanel();
        if (!panel || !parentDoc?.body) return panel || null;

        if (panel.ownerDocument !== parentDoc || panel.parentNode !== parentDoc.body) {
          parentDoc.body.appendChild(panel);
        }

        panel.style.setProperty('position', 'fixed', 'important');
        panel.style.setProperty('inset', '0', 'important');
        panel.style.setProperty('width', '100vw', 'important');
        panel.style.setProperty('height', '100dvh', 'important');
        panel.style.setProperty('min-height', '100vh', 'important');
        panel.style.setProperty('z-index', '2147482000', 'important');
        panel.style.setProperty('pointer-events', 'auto', 'important');
        return panel;
      } catch (error) {
        console.warn('[预设工坊][Mobile FAB] 主面板迁移到顶层 document 失败', error);
        return null;
      }
    }

    /* 不能只凭同名节点存在就判定成功：刷新后可能留下 display:none 的旧面板。 */
    function mainPanelExists() {
      return getMainPanelCandidates().some(panelIsVisible);
    }

    async function waitForVisibleMainPanel(timeout = 800) {
      const deadline = Date.now() + timeout;
      do {
        ensureMainPanelInTopDocument();
        if (mainPanelExists()) return true;
        await new Promise(resolve => setTimeout(resolve, 50));
      } while (Date.now() < deadline);
      return false;
    }

    let openingPromise = null;

    async function runOpenManager() {
      /* 已经可见时只把面板迁到顶层，不再调用 toggle，避免把它反向关闭。 */
      if (mainPanelExists()) {
        ensureMainPanelInTopDocument();
        return true;
      }

      /* 第一优先：直接复用本体自己的 toggleMainPanel / fo() */
      try {
        if (typeof fo === 'function') {
          fo();
          if (await waitForVisibleMainPanel()) return true;
        }
      } catch (error) {
        console.warn('[预设工坊][Mobile FAB] fo() 打开失败，尝试事件通道', error);
      }

      /* 第二优先：走预设工坊本体已经注册的“打开预设管家”事件 */
      try {
        if (typeof getButtonEvent === 'function' && typeof eventEmit === 'function') {
          const evtName = getButtonEvent('打开预设管家');
          if (evtName) {
            eventEmit(evtName);
            if (await waitForVisibleMainPanel()) return true;
          }
        }
      } catch (error) {
        console.warn('[预设工坊][Mobile FAB] 事件通道打开失败', error);
      }

      /* 第三兜底：点击本体隐藏的原浮动面板中的可点击节点 */
      try {
        const original =
          doc.querySelector('#preset-manager-floating-panel button, #preset-manager-floating-panel [role="button"]') ||
          parentDoc?.querySelector?.('#preset-manager-floating-panel button, #preset-manager-floating-panel [role="button"]');
        if (original) {
          original.click();
          if (await waitForVisibleMainPanel()) return true;
        }
      } catch (error) {
        console.warn('[预设工坊][Mobile FAB] 原浮动入口兜底失败', error);
      }

      /* 不再静默失败：真打不开时至少给出明确提示。 */
      try {
        const toast = (typeof toastr !== 'undefined') ? toastr : window.parent?.toastr;
        if (toast?.error) toast.error('预设工坊没有成功打开，请刷新酒馆页面后再试');
      } catch (_) {}
      return false;
    }

    /*
     * Android 常在 click 后再补 touchend；面板加载稍慢时两次 toggle 会刚打开又关闭。
     * 所有入口共用同一个 Promise，直到本次打开完成前都不会重复触发。
     */
    function openManager() {
      if (openingPromise) return openingPromise;
      openingPromise = runOpenManager().finally(() => {
        openingPromise = null;
      });
      return openingPromise;
    }

    try {
      parentDoc.__pmmWorkshopOpenBridge = { token: FAB_RUNTIME_TOKEN, open: openManager };
    } catch (_) {}

    function onPointerDown(ev) {
      if (typeof ev.button === 'number' && ev.button !== 0) return;

      dragging = true;
      moved = false;
      suppressClick = false;
      pointerId = ev.pointerId;
      startClientX = ev.clientX;
      startClientY = ev.clientY;
      startX = x;
      startY = y;

      snap = '';
      clearSnapClass();
      b.classList.add('pmm-fab-dragging');

      try { b.setPointerCapture(pointerId); } catch (_) {}
      ev.preventDefault();
    }

    function onPointerMove(ev) {
      if (!dragging || (pointerId !== null && ev.pointerId !== pointerId)) return;

      const dx = ev.clientX - startClientX;
      const dy = ev.clientY - startClientY;
      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) moved = true;

      const p = clampPosition(startX + dx, startY + dy);
      x = p.x;
      y = p.y;
      b.style.left = Math.round(x) + 'px';
      b.style.top = Math.round(y) + 'px';
      ev.preventDefault();
    }

    function finishPointer(ev) {
      if (!dragging || (pointerId !== null && ev.pointerId !== pointerId)) return;

      dragging = false;
      b.classList.remove('pmm-fab-dragging');
      try { b.releasePointerCapture(pointerId); } catch (_) {}
      pointerId = null;

      if (moved) {
        /* 拖动后 Safari 还会补一个 click；只屏蔽那一次，避免误打开。 */
        suppressClick = true;
        settleToEdge();
        setTimeout(() => { suppressClick = false; }, 260);
        ev.preventDefault();
      } else {
        /* 关键修复：轻点时不要在 pointerup 里打开，也不要 preventDefault。
           让 iOS Safari 正常产生 click，再由 click 统一打开。 */
        applyPosition();
      }

      ev.stopPropagation();
    }

    function cancelPointer(ev) {
      if (!dragging) return;
      dragging = false;
      b.classList.remove('pmm-fab-dragging');
      pointerId = null;
      applyPosition();
      /* pointercancel 不代表用户完成点击，所以这里既不打开，也不永久吞 click */
    }

    b.addEventListener('pointerdown', onPointerDown, { passive: false });
    b.addEventListener('pointermove', onPointerMove, { passive: false });
    b.addEventListener('pointerup', finishPointer, { passive: false });
    b.addEventListener('pointercancel', cancelPointer, { passive: true });

    /* iPhone/Safari：真正的“轻点打开”统一走 click，避免 pointer capture 差异。 */
    b.addEventListener('click', ev => {
      ev.preventDefault();
      ev.stopPropagation();
      if (suppressClick || moved) {
        moved = false;
        return;
      }
      openManager();
    }, { passive: false });

    /* 某些 iOS WebKit 情况下 click 被页面手势层吞掉，touchend 再做一次延迟兜底。
       如果 click 已经成功打开，mainPanelExists() 会阻止重复切换。 */
    b.addEventListener('touchend', () => {
      if (dragging || moved || suppressClick) return;
      setTimeout(() => {
        if (!mainPanelExists()) openManager();
      }, 140);
    }, { passive: true });

    function fitAfterResize() {
      const p = clampPosition(x, y);
      x = p.x;
      y = p.y;

      if (snap === 'right') {
        const vp = viewport();
        x = vp.w - SIZE - SIDE_MARGIN;
      } else if (snap === 'left') {
        x = SIDE_MARGIN;
      }

      applyPosition();
      save();
    }

    const onOrientationChange = () => setTimeout(fitAfterResize, 150);
    win.addEventListener('resize', fitAfterResize);
    win.addEventListener('orientationchange', onOrientationChange);

    /* 下次脚本热重载时主动解除 window 监听，再由新实例重新绑定。 */
    b.__pmmFabCleanup = () => {
      try { win.removeEventListener('resize', fitAfterResize); } catch (_) {}
      try { win.removeEventListener('orientationchange', onOrientationChange); } catch (_) {}
    };

    restore();
    applyPosition();
  }

  function visiblePanelContainer(doc) {
    const arr = Array.from(doc.querySelectorAll('.pm-panel-container'));
    return arr.find(el => {
      const r = el.getBoundingClientRect();
      const st = doc.defaultView ? doc.defaultView.getComputedStyle(el) : null;
      return r.width > 0 && r.height > 0 && (!st || (st.display !== 'none' && st.visibility !== 'hidden'));
    }) || null;
  }

  function promptByName(panel, name) {
    if (!panel || !name) return null;
    const items = Array.from(panel.querySelectorAll('.prompt-item'));
    return items.find(item => {
      const n = item.querySelector('.prompt-card__name');
      return n && (n.textContent || '').trim() === name;
    }) || items.find(item => {
      const n = item.querySelector('.prompt-card__name');
      return n && (n.textContent || '').trim().includes(name);
    }) || null;
  }

  function ensureExpanded(item) {
    if (!item || item.querySelector('.inline-editor__textarea, textarea')) return;
    const card = item.querySelector('.prompt-card');
    try { (card || item).click(); } catch (_) {}
  }

  function promptText(item) {
    if (!item) return '';
    const ta = item.querySelector('.inline-editor__textarea, textarea');
    if (ta) return ta.value || ta.textContent || '';
    const ed = item.querySelector('.inline-editor');
    return ed ? (ed.innerText || ed.textContent || '') : '';
  }

  function esc(s) {
    return String(s || '').replace(/[&<>"']/g, c => ({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
    })[c]);
  }

  function normalizePromptForCompare(text) {
    return String(text ?? '')
      .normalize('NFC')
      .replace(/
?/g, '
')
      .replace(/[​-‍﻿]/g, '')
      .replace(/ /g, ' ')
      .split('
')
      .map(line => line.replace(/[ 	]+$/g, ''))
      .join('
')
      .trim();
  }

  function tokenizeDiffText(text) {
    /* 中文逐字，英文/数字按词，空白成组；既能精确标中文，又不会把英文拆得太碎 */
    return String(text || '').match(/[㐀-鿿]|[A-Za-z0-9_]+|\s+|[^\s]/gu) || [];
  }

  function sameRun(a, ai, b, bi, need = 3) {
    let count = 0;
    while (ai + count < a.length && bi + count < b.length && a[ai + count] === b[bi + count]) {
      count++;
      if (count >= need) return true;
    }
    return count >= need || (ai + count === a.length && bi + count === b.length && count > 0);
  }

  function buildHighlightedDiff(leftText, rightText) {
    const left = tokenizeDiffText(leftText);
    const right = tokenizeDiffText(rightText);
    const outA = [];
    const outB = [];
    let i = 0, j = 0;
    const WINDOW = 48;

    const pushSame = token => {
      const h = esc(token);
      outA.push(h);
      outB.push(h);
    };
    const pushDiffA = tokens => {
      if (!tokens.length) return;
      outA.push('<mark class="pmm-diff-mark pmm-diff-mark-a">' + esc(tokens.join('')) + '</mark>');
    };
    const pushDiffB = tokens => {
      if (!tokens.length) return;
      outB.push('<mark class="pmm-diff-mark pmm-diff-mark-b">' + esc(tokens.join('')) + '</mark>');
    };

    while (i < left.length || j < right.length) {
      if (i < left.length && j < right.length && left[i] === right[j]) {
        pushSame(left[i]);
        i++; j++;
        continue;
      }

      if (i >= left.length) {
        pushDiffB(right.slice(j));
        j = right.length;
        break;
      }
      if (j >= right.length) {
        pushDiffA(left.slice(i));
        i = left.length;
        break;
      }

      let best = null;
      const maxA = Math.min(WINDOW, left.length - i);
      const maxB = Math.min(WINDOW, right.length - j);

      /* 在附近寻找重新对齐点。允许单边插入/删除。 */
      for (let da = 0; da <= maxA; da++) {
        for (let db = 0; db <= maxB; db++) {
          if (da === 0 && db === 0) continue;
          if (i + da >= left.length || j + db >= right.length) continue;
          if (left[i + da] !== right[j + db]) continue;
          if (!sameRun(left, i + da, right, j + db, 3)) continue;

          const cost = da + db + Math.abs(da - db) * .15;
          if (!best || cost < best.cost) best = { da, db, cost };
        }
      }

      if (best) {
        pushDiffA(left.slice(i, i + best.da));
        pushDiffB(right.slice(j, j + best.db));
        i += best.da;
        j += best.db;
      } else {
        /* 找不到近距离对齐点时，用公共后缀兜底，避免把末尾相同部分全涂黄 */
        let suffix = 0;
        while (
          left.length - 1 - suffix >= i &&
          right.length - 1 - suffix >= j &&
          left[left.length - 1 - suffix] === right[right.length - 1 - suffix]
        ) suffix++;

        const aEnd = left.length - suffix;
        const bEnd = right.length - suffix;
        pushDiffA(left.slice(i, aEnd));
        pushDiffB(right.slice(j, bEnd));

        for (let k = 0; k < suffix; k++) {
          pushSame(left[aEnd + k]);
        }
        i = left.length;
        j = right.length;
      }
    }

    return { leftHtml: outA.join(''), rightHtml: outB.join('') };
  }


  function presetNameFromPanel(panel) {
    if (!panel) return '未识别预设';

    const select = panel.querySelector('.title-select');
    if (select) {
      return (select.value || select.options?.[select.selectedIndex]?.textContent || '').trim() || '未命名预设';
    }

    const input = panel.querySelector('.title-input');
    if (input && (input.value || '').trim()) return input.value.trim();

    const text = panel.querySelector('.title-text');
    if (text && (text.textContent || '').trim()) return text.textContent.trim();

    return '未识别预设';
  }

  function setNativeTextareaValue(textarea, value) {
    if (!textarea) return;
    try {
      const proto = textarea.ownerDocument?.defaultView?.HTMLTextAreaElement?.prototype || HTMLTextAreaElement.prototype;
      const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
      if (setter) setter.call(textarea, value);
      else textarea.value = value;
    } catch (_) {
      textarea.value = value;
    }

    const win = textarea.ownerDocument?.defaultView || window;
    try {
      textarea.dispatchEvent(new win.Event('input', { bubbles: true }));
    } catch (_) {
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    }
  }

  async function waitForElement(getter, timeout = 900) {
    const started = Date.now();
    while (Date.now() - started < timeout) {
      const el = getter();
      if (el) return el;
      await new Promise(resolve => setTimeout(resolve, 35));
    }
    return null;
  }

  async function writeContentBackToPanel(item, panel, newContent) {
    if (!item || !panel) throw new Error('没有找到对应的预设条目');

    ensureExpanded(item);

    const textarea = await waitForElement(
      () => item.querySelector('.inline-editor__textarea, textarea'),
      1200
    );
    if (!textarea) throw new Error('没有找到条目编辑框');

    setNativeTextareaValue(textarea, newContent);

    /* PromptInlineEditor 在 blur 时 commitChanges -> emit update -> 写回 Vue store */
    try {
      textarea.dispatchEvent(new (textarea.ownerDocument.defaultView || window).FocusEvent('blur', { bubbles: false }));
    } catch (_) {
      textarea.dispatchEvent(new Event('blur'));
    }
    textarea.dispatchEvent(new Event('change', { bubbles: true }));

    await new Promise(resolve => setTimeout(resolve, 90));

    /* 每一侧都有自己的 PresetPanel 保存按钮：
       左侧保存当前预设，右侧 MergePanel 保存 rightPresetName。 */
    const saveBtn =
      panel.querySelector('button.header-card.action-card[title="保存"]') ||
      panel.querySelector('button.action-card[title="保存"]') ||
      panel.querySelector('button[title="保存"]');

    if (!saveBtn) throw new Error('没有找到该预设的保存按钮');

    saveBtn.click();

    /* 给原本的异步 setPreset 一点时间完成。 */
    await new Promise(resolve => setTimeout(resolve, 450));
  }

  function showContentDiff(doc, name, a, b, ctx = {}) {
    /* 1.3.17：内容编辑页也挂在主面板 root 内，不再跨 document。 */
    const sourcePanel = ctx.leftPanel || ctx.rightPanel || null;
    const sourceDoc = sourcePanel?.ownerDocument || doc;
    const mainRoot =
      sourceDoc.getElementById('preset-manager-main-panel') ||
      doc.getElementById?.('preset-manager-main-panel') ||
      null;

    doc = mainRoot?.ownerDocument || sourceDoc;
    const host = mainRoot || doc.body;

    const old = host.querySelector('.pmm-content-diff-overlay');
    if (old) old.remove();

    let leftRaw = String(a || '');
    let rightRaw = String(b || '');
    let originalLeft = leftRaw;
    let originalRight = rightRaw;

    const leftPresetName = ctx.leftPresetName || presetNameFromPanel(ctx.leftPanel);
    const rightPresetName = ctx.rightPresetName || presetNameFromPanel(ctx.rightPanel);

    const overlay = doc.createElement('div');
    overlay.className = 'pmm-content-diff-overlay';
    overlay.style.setProperty('position', 'absolute', 'important');
    overlay.style.setProperty('inset', '0', 'important');
    overlay.style.setProperty('z-index', '12100', 'important');
    overlay.style.setProperty('pointer-events', 'auto', 'important');

    const box = doc.createElement('div');
    box.className = 'pmm-content-diff';

    box.innerHTML = `
      <div class="pmm-content-diff-head">
        <button class="pmm-content-diff-back" type="button" title="返回比对详情"><i class="fa-solid fa-arrow-left"></i></button>
        <div class="pmm-content-diff-title"><i class="fa-solid fa-code-compare" style="margin-right:5px"></i>${esc(name || '内容差异')}</div>
        <div></div>
      </div>
      <div class="pmm-content-diff-body">
        <div class="pmm-diff-summary-slot"></div>

        <div class="pmm-diff-side" data-side="left">
          <div class="pmm-diff-label">
            <span style="color:#ef4444;font-weight:800">A</span>
            <strong>上侧预设</strong>
            <span class="pmm-diff-preset-name" title="${esc(leftPresetName)}">｜ ${esc(leftPresetName)}</span>
            <span class="pmm-diff-side-dirty">已修改</span>
            <button class="pmm-diff-edit-btn" type="button"><i class="fa-solid fa-pen"></i><span>编辑</span></button>
          </div>
          <pre class="pmm-diff-preview"></pre>
          <textarea class="pmm-diff-edit-area" spellcheck="false"></textarea>
        </div>

        <div class="pmm-diff-side" data-side="right">
          <div class="pmm-diff-label">
            <span style="color:#3b82f6;font-weight:800">B</span>
            <strong>下侧预设</strong>
            <span class="pmm-diff-preset-name" title="${esc(rightPresetName)}">｜ ${esc(rightPresetName)}</span>
            <span class="pmm-diff-side-dirty">已修改</span>
            <button class="pmm-diff-edit-btn" type="button"><i class="fa-solid fa-pen"></i><span>编辑</span></button>
          </div>
          <pre class="pmm-diff-preview"></pre>
          <textarea class="pmm-diff-edit-area" spellcheck="false"></textarea>
        </div>

        <div class="pmm-diff-savebar">
          <div class="pmm-diff-save-note">点正文或「编辑」即可修改；保存会直接写回 A / B 对应预设。</div>
          <button class="pmm-diff-save-btn" type="button" disabled>
            <i class="fa-solid fa-floppy-disk"></i><span>保存修改</span>
          </button>
        </div>
      </div>`;

    overlay.appendChild(box);
    host.appendChild(overlay);

    const noteSlot = box.querySelector('.pmm-diff-summary-slot');
    const leftSide = box.querySelector('[data-side="left"]');
    const rightSide = box.querySelector('[data-side="right"]');
    const leftPreview = leftSide.querySelector('.pmm-diff-preview');
    const rightPreview = rightSide.querySelector('.pmm-diff-preview');
    const leftEdit = leftSide.querySelector('.pmm-diff-edit-area');
    const rightEdit = rightSide.querySelector('.pmm-diff-edit-area');
    const saveBtn = box.querySelector('.pmm-diff-save-btn');

    leftEdit.value = leftRaw;
    rightEdit.value = rightRaw;

    function isDirty() {
      return leftEdit.value !== originalLeft || rightEdit.value !== originalRight;
    }

    function updateDirtyUI() {
      leftSide.classList.toggle('is-dirty', leftEdit.value !== originalLeft);
      rightSide.classList.toggle('is-dirty', rightEdit.value !== originalRight);
      saveBtn.disabled = !isDirty();
    }

    function updatePreview() {
      leftRaw = leftEdit.value;
      rightRaw = rightEdit.value;

      const normalizedEqual =
        normalizePromptForCompare(leftRaw) === normalizePromptForCompare(rightRaw);
      const exactEqual = leftRaw === rightRaw;
      const diff = buildHighlightedDiff(leftRaw, rightRaw);

      if (exactEqual) {
        noteSlot.innerHTML =
          '<div class="pmm-diff-summary-note is-equal"><i class="fa-solid fa-circle-check" style="margin-right:5px;color:#10b981"></i>两侧原始正文逐字完全一致。</div>';
      } else if (normalizedEqual) {
        noteSlot.innerHTML =
          '<div class="pmm-diff-summary-note is-equal"><i class="fa-solid fa-wand-magic-sparkles" style="margin-right:5px;color:#10b981"></i>可见正文一致，差异仅来自换行格式、尾部空格、NBSP 或零宽字符。</div>';
      } else {
        noteSlot.innerHTML =
          '<div class="pmm-diff-summary-note"><i class="fa-solid fa-highlighter" style="margin-right:5px;color:#eab308"></i>黄色荧光标记 = 两侧真正不同的文字。点击正文即可直接编辑。</div>';
      }

      leftPreview.innerHTML = leftRaw ? diff.leftHtml : '（未读取到内容）';
      rightPreview.innerHTML = rightRaw ? diff.rightHtml : '（未读取到内容）';
      updateDirtyUI();
    }

    function setEditing(sideEl, on) {
      sideEl.classList.toggle('is-editing', on);
      const btn = sideEl.querySelector('.pmm-diff-edit-btn');
      btn.classList.toggle('is-editing', on);
      btn.innerHTML = on
        ? '<i class="fa-solid fa-highlighter"></i><span>高亮</span>'
        : '<i class="fa-solid fa-pen"></i><span>编辑</span>';

      if (!on) updatePreview();
      else {
        const ta = sideEl.querySelector('.pmm-diff-edit-area');
        setTimeout(() => {
          try { ta.focus(); } catch (_) {}
        }, 30);
      }
    }

    [leftSide, rightSide].forEach(sideEl => {
      const preview = sideEl.querySelector('.pmm-diff-preview');
      const editBtn = sideEl.querySelector('.pmm-diff-edit-btn');
      preview.addEventListener('click', () => setEditing(sideEl, true));
      editBtn.addEventListener('click', () => {
        setEditing(sideEl, !sideEl.classList.contains('is-editing'));
      });
    });

    leftEdit.addEventListener('input', updateDirtyUI);
    rightEdit.addEventListener('input', updateDirtyUI);

    saveBtn.addEventListener('click', async () => {
      if (!isDirty()) return;

      saveBtn.classList.add('is-saving');
      saveBtn.disabled = true;
      saveBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i><span>保存中…</span>';

      try {
        const leftChanged = leftEdit.value !== originalLeft;
        const rightChanged = rightEdit.value !== originalRight;

        if (leftChanged) {
          await writeContentBackToPanel(ctx.leftItem, ctx.leftPanel, leftEdit.value);
        }
        if (rightChanged) {
          await writeContentBackToPanel(ctx.rightItem, ctx.rightPanel, rightEdit.value);
        }

        /* 保存后更新本窗口基线，这样不会一直显示“已修改”。 */
        leftRaw = leftEdit.value;
        rightRaw = rightEdit.value;
        originalLeft = leftRaw;
        originalRight = rightRaw;

        leftSide.classList.remove('is-dirty', 'is-editing');
        rightSide.classList.remove('is-dirty', 'is-editing');

        updatePreview();

        saveBtn.innerHTML = '<i class="fa-solid fa-circle-check"></i><span>已保存</span>';
        saveBtn.style.setProperty('color', '#10b981', 'important');

        const saveNote = box.querySelector('.pmm-diff-save-note');
        saveNote.textContent = '修改已写回对应预设。返回详情后重新点一次「比对」即可刷新差异结果。';

        setTimeout(() => {
          saveBtn.classList.remove('is-saving');
          saveBtn.disabled = true;
          saveBtn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i><span>保存修改</span>';
        }, 1100);
      } catch (error) {
        console.error('[预设工坊][Diff Edit] 保存失败', error);
        saveBtn.classList.remove('is-saving');
        saveBtn.disabled = false;
        saveBtn.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i><span>保存失败</span>';
        const saveNote = box.querySelector('.pmm-diff-save-note');
        saveNote.textContent = '保存失败：' + (error?.message || '未知错误') + '。原预设不会因为这个弹窗自动删除内容。';
      }
    });

    updatePreview();

    box.querySelector('.pmm-content-diff-back').addEventListener('click', () => overlay.remove());
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  }
  function openContentDiff(doc, name) {
    const pc = visiblePanelContainer(doc);
    if (!pc) return;

    const panels = Array.from(pc.querySelectorAll('.preset-panel')).filter(el => {
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    });
    if (panels.length < 2) return;

    let leftName = name;
    let rightName = name;

    /* 兼容原“正文相似”的展示名：左侧名称 ≈ 右侧名称 */
    if (name && name.indexOf('≈') !== -1) {
      const parts = name.split('≈');
      if (parts.length >= 2) {
        leftName = (parts[0] || '').trim();
        rightName = parts.slice(1).join('≈').trim();
      }
    }

    const left = promptByName(panels[0], leftName);
    const right = promptByName(panels[1], rightName);
    if (!left || !right) return;

    ensureExpanded(left);
    ensureExpanded(right);

    setTimeout(() => {
      showContentDiff(
        doc,
        name,
        promptText(left),
        promptText(right),
        {
          leftItem: left,
          rightItem: right,
          leftPanel: panels[0],
          rightPanel: panels[1],
          leftPresetName: presetNameFromPanel(panels[0]),
          rightPresetName: presetNameFromPanel(panels[1]),
        }
      );
    }, 180);
  }

  function fixDiffDetail(doc) {
    if (!isMobile()) return;

    const root = doc.getElementById('preset-manager-main-panel');
    if (!root) return;

    const portalId = 'pmm-diff-detail-portal';
    const existingPortal = doc.getElementById(portalId);

    /* 如果 Vue 原详情已经关闭，清掉我们的显示层。 */
    if (existingPortal) {
      const originalOverlay = doc.querySelector('[data-pmm-diff-original="1"]');
      if (!originalOverlay || !originalOverlay.isConnected) {
        existingPortal.remove();
      }
      return;
    }

    /* 一定找原 Vue modal，不找我们自己的 clone。 */
    const titleSpan = Array.from(doc.querySelectorAll('span')).find(s => {
      if ((s.textContent || '').trim() !== '比对结果详情') return false;
      return !s.closest('#' + portalId);
    });
    if (!titleSpan) return;

    const title = titleSpan.parentElement;
    const header = title && title.parentElement;
    const modal = header && header.parentElement;
    const overlay = modal && modal.parentElement;
    if (!modal || !overlay) return;

    /* Vue 原件不移动，只隐藏。Vue 仍然完全拥有它。 */
    overlay.dataset.pmmDiffOriginal = '1';
    overlay.style.setProperty('visibility', 'hidden', 'important');
    overlay.style.setProperty('pointer-events', 'none', 'important');

    /* 创建直属 root 的真正全屏显示层。 */
    const portal = doc.createElement('div');
    portal.id = portalId;
    portal.style.setProperty('position', 'fixed', 'important');
    portal.style.setProperty('inset', '0', 'important');
    portal.style.setProperty('height', '100dvh', 'important');
    portal.style.setProperty('max-height', '100dvh', 'important');
