    portal.style.setProperty('background', 'rgba(0,0,0,.52)', 'important');
    portal.style.setProperty('backdrop-filter', 'blur(7px)', 'important');
    portal.style.setProperty('-webkit-backdrop-filter', 'blur(7px)', 'important');
    portal.style.setProperty('overflow', 'hidden', 'important');
    portal.style.setProperty('pointer-events', 'auto', 'important');

    const clone = modal.cloneNode(true);
    clone.dataset.pmmDiffPortalModal = '1';
    clone.style.setProperty('flex', '1 1 auto', 'important');
    clone.style.setProperty('width', '100%', 'important');
    clone.style.setProperty('height', 'auto', 'important');
    clone.style.setProperty('max-width', 'none', 'important');
    clone.style.setProperty('max-height', '100%', 'important');
    clone.style.setProperty('min-height', '0', 'important');
    clone.style.setProperty('margin', '0', 'important');
    clone.style.setProperty('display', 'flex', 'important');
    clone.style.setProperty('flex-direction', 'column', 'important');
    clone.style.setProperty('overflow', 'hidden', 'important');
    clone.style.setProperty('border-radius', '14px', 'important');

    portal.appendChild(clone);
    root.appendChild(portal);

    const children = Array.from(clone.children);
    const head = children[0];
    const stats = children[1];
    const list = children[2];
    const footer = children[3];

    if (head) {
      head.style.setProperty('flex', '0 0 auto', 'important');
      head.style.setProperty('padding', '8px 10px', 'important');

      /* 右下角已有“关闭”，iOS 手机端隐藏重复的右上角 X。 */
      const topCloseBtn = Array.from(head.querySelectorAll('button')).find(btn => btn.querySelector('.fa-xmark'));
      if (topCloseBtn) topCloseBtn.style.setProperty('display', 'none', 'important');
