    if (stats) {
      const statCards = Array.from(stats.children);

      /* “正文相似”保持独立统计，不再并入“内容不同”。 */
      stats.style.setProperty('flex', '0 0 auto', 'important');
      stats.style.setProperty('display', 'grid', 'important');
      stats.style.setProperty('grid-template-columns', 'repeat(6,minmax(0,1fr))', 'important');
      stats.style.setProperty('gap', '2px', 'important');
      stats.style.setProperty('padding', '5px', 'important');

      statCards.forEach(card => {
        /* 六张统计卡统一为：图标 → 标题 → 数字。 */
        card.style.setProperty('display', 'flex', 'important');
        card.style.setProperty('flex-direction', 'column', 'important');
        card.style.setProperty('align-items', 'center', 'important');
        card.style.setProperty('justify-content', 'center', 'important');
        card.style.setProperty('gap', '2px', 'important');
        card.style.setProperty('min-width', '0', 'important');
        card.style.setProperty('min-height', '48px', 'important');
        card.style.setProperty('padding', '3px 1px', 'important');

        const icon = card.querySelector('i');
        if (icon) {
          icon.style.setProperty('display', 'block', 'important');
          icon.style.setProperty('flex', '0 0 auto', 'important');
          icon.style.setProperty('margin', '0', 'important');
        }

        Array.from(card.querySelectorAll('span')).forEach(sp => {
          const tx = (sp.textContent || '').trim();
          sp.style.setProperty('display', 'block', 'important');
          sp.style.setProperty('text-align', 'center', 'important');
          sp.style.setProperty('line-height', '1.15', 'important');
          if (/^\d+$/.test(tx)) {
            sp.style.setProperty('font-size', '15px', 'important');
            sp.style.setProperty('margin-top', '1px', 'important');
          } else {
            sp.style.setProperty('font-size', '7px', 'important');
            sp.style.setProperty('white-space', 'nowrap', 'important');
            sp.style.setProperty('margin', '0', 'important');
