    if (list) {
      list.style.setProperty('flex', '1 1 auto', 'important');
      list.style.setProperty('min-height', '0', 'important');
      list.style.setProperty('display', 'flex', 'important');
      list.style.setProperty('flex-direction', 'column', 'important');
      list.style.setProperty('overflow', 'hidden', 'important');

      const lk = Array.from(list.children);
      if (lk[0]) lk[0].style.setProperty('flex', '0 0 auto', 'important');
      if (lk[1]) {
        lk[1].style.setProperty('flex', '1 1 auto', 'important');
        lk[1].style.setProperty('min-height', '0', 'important');
        lk[1].style.setProperty('max-height', 'none', 'important');
        lk[1].style.setProperty('overflow-y', 'auto', 'important');
        lk[1].style.setProperty('-webkit-overflow-scrolling', 'touch', 'important');
      }

      /* 独有项整行可点击；只给 clone 的列表绑定一个委托监听器。 */
      const uniqueStatusTexts = new Set(['仅上侧预设存在', '仅下侧预设存在']);

      const directRowName = row => {
        if (!row) return '';
        const spans = Array.from(row.children).filter(el => el.tagName === 'SPAN');
        const nameEl = spans.find(el => {
          const tx = (el.textContent || '').trim();
          return tx &&
            !uniqueStatusTexts.has(tx) &&
            !/^[A-Z]{1,2}$/.test(tx) &&
            !/^\d{1,3}%$/.test(tx);
        });
        return nameEl ? (nameEl.textContent || '').trim() : '';
      };

      /* 右侧状态下面显示“点击跳转 ›”，条目名过长允许换行。 */
      if (!doc.getElementById('pmm-unique-jump-hint-style')) {
        const jumpStyle = doc.createElement('style');
        jumpStyle.id = 'pmm-unique-jump-hint-style';
        jumpStyle.textContent = `
          .pmm-unique-jump-status {
            display: inline-flex !important;
            flex-direction: column !important;
            align-items: center !important;
            justify-content: center !important;
            gap: 1px !important;
            flex: 0 0 auto !important;
            white-space: nowrap !important;
            line-height: 1.08 !important;
          }
          .pmm-unique-jump-status::after {
            content: '点击跳转 ›';
            display: block;
            font-size: 6.5px;
            font-weight: 500;
            opacity: .62;
            line-height: 1;
            letter-spacing: 0;
            text-decoration: none;
            pointer-events: none;
          }
          .pmm-unique-jump-name {
            flex: 1 1 auto !important;
            min-width: 0 !important;
            max-width: none !important;
            white-space: normal !important;
            overflow: visible !important;
            text-overflow: clip !important;
            overflow-wrap: anywhere !important;
            word-break: break-word !important;
            line-height: 1.28 !important;
          }
        `;
        (doc.head || doc.documentElement).appendChild(jumpStyle);
      }

      Array.from(list.querySelectorAll('span')).forEach(statusEl => {
        const statusText = (statusEl.textContent || '').trim();
        if (!uniqueStatusTexts.has(statusText)) return;
        const row = statusEl.parentElement;
        if (!row) return;

        row.style.setProperty('cursor', 'pointer', 'important');
        row.style.setProperty('align-items', 'center', 'important');
        row.style.setProperty('min-height', '0', 'important');
        statusEl.classList.add('pmm-unique-jump-status');

        const spans = Array.from(row.children).filter(el => el.tagName === 'SPAN');
        const nameEl = spans.find(el => {
          const tx = (el.textContent || '').trim();
          return tx &&
            !uniqueStatusTexts.has(tx) &&
            !/^[A-Z]{1,2}$/.test(tx) &&
            !/^\d{1,3}%$/.test(tx);
        });
        if (nameEl) nameEl.classList.add('pmm-unique-jump-name');

        row.title = statusText === '仅上侧预设存在'
          ? '点击定位到上侧预设中的这个条目'
          : '点击定位到下侧预设中的这个条目';
      });

      if (!list.dataset.pmmUniqueJumpBound) {
        list.dataset.pmmUniqueJumpBound = '1';

        list.addEventListener('click', ev => {
          const targetNode = ev.target;
          if (!targetNode || typeof targetNode.closest !== 'function') return;

          const row = targetNode.closest('div');
          if (!row || !list.contains(row)) return;

          const directSpans = Array.from(row.children).filter(el => el.tagName === 'SPAN');
          const statusEl = directSpans.find(el => uniqueStatusTexts.has((el.textContent || '').trim()));
          if (!statusEl) return;

          const statusText = (statusEl.textContent || '').trim();
          const name = directRowName(row);
          if (!name) return;

          ev.preventDefault();
          ev.stopPropagation();

          /* 同名重复条目按同一侧的出现顺序定位。 */
          const sameSideRows = Array.from(list.querySelectorAll('span'))
            .filter(el => (el.textContent || '').trim() === statusText)
            .map(el => el.parentElement)
            .filter(Boolean);

          const sameNameRows = sameSideRows.filter(r => directRowName(r) === name);
          const occurrence = Math.max(0, sameNameRows.indexOf(row));

          /* iOS 版本继续沿用原来的 portal 关闭机制，不移动 Vue 原件。 */
          closePortal();

          setTimeout(() => {
            const pc = visiblePanelContainer(doc);
            if (!pc) return;

            const panels = Array.from(pc.querySelectorAll('.preset-panel')).filter(el => {
              const r = el.getBoundingClientRect();
              const st = doc.defaultView ? doc.defaultView.getComputedStyle(el) : null;
              return r.width > 0 && r.height > 0 &&
                (!st || (st.display !== 'none' && st.visibility !== 'hidden'));
            });

            const sideIndex = statusText === '仅上侧预设存在' ? 0 : 1;
            const panel = panels[sideIndex];
            if (!panel) return;

            const exactItems = Array.from(panel.querySelectorAll('.prompt-item')).filter(item => {
              const n = item.querySelector('.prompt-card__name');
              return n && (n.textContent || '').trim() === name;
            });

            const targetItem = exactItems[occurrence] || exactItems[0] || promptByName(panel, name);
            if (!targetItem) return;

            try {
              targetItem.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
            } catch (_) {
              try { targetItem.scrollIntoView(); } catch (_) {}
            }

            const card = targetItem.querySelector('.prompt-card') || targetItem;
            const oldShadow = card.style.getPropertyValue('box-shadow');
            const oldShadowPriority = card.style.getPropertyPriority('box-shadow');
            const glow = sideIndex === 0
              ? '0 0 0 2px rgba(168,85,247,.85), 0 0 18px rgba(168,85,247,.32)'
              : '0 0 0 2px rgba(59,130,246,.85), 0 0 18px rgba(59,130,246,.32)';

            card.style.setProperty('box-shadow', glow, 'important');

            setTimeout(() => {
              if (oldShadow) card.style.setProperty('box-shadow', oldShadow, oldShadowPriority || '');
              else card.style.removeProperty('box-shadow');
            }, 1400);
          }, 260);
        });
      }
    }

    if (footer) {
      footer.style.setProperty('flex', '0 0 auto', 'important');
      footer.style.setProperty('padding', '5px 8px 7px', 'important');
    }

    /* “正文相似”保持独立金色状态；百分比直接表示正文文字相似度。 */
    Array.from(clone.querySelectorAll('span')).forEach(sp => {
      if ((sp.textContent || '').trim() !== '正文相似') return;

      sp.title = '正文文字相似度达到 60% 以上';
      sp.style.setProperty('color', '#eab308', 'important');
      sp.style.setProperty('background', 'rgba(234,179,8,.12)', 'important');
      sp.style.setProperty('border-color', 'rgba(234,179,8,.32)', 'important');

      const row = sp.parentElement;
      if (row) {
        Array.from(row.querySelectorAll('span')).forEach(badge => {
          const tx = (badge.textContent || '').trim();
          if (!/^[A-Z]{1,2}$/.test(tx)) return;
          badge.style.setProperty('color', '#eab308', 'important');
          badge.style.setProperty('background', 'rgba(234,179,8,.10)', 'important');
          badge.style.setProperty('border-color', 'rgba(234,179,8,.35)', 'important');
        });

        Array.from(row.querySelectorAll('span,div')).forEach(el => {
          if (/^\d{1,3}%$/.test((el.textContent || '').trim())) {
            el.title = '正文文字相似度';
          }
        });
      }
    });

    /* 百分比显示差异率。clone 每次只生成一次，所以不会重复翻转。 */
    Array.from(clone.querySelectorAll('span')).forEach(statusEl => {
      if ((statusEl.textContent || '').trim() !== '内容不同') return;
      const row = statusEl.parentElement;
      if (!row) return;

      const candidates = Array.from(row.querySelectorAll('span, div')).filter(el => {
        if (el === statusEl) return false;
        return /^\d{1,3}%$/.test((el.textContent || '').trim());
      });

      candidates.forEach(percentEl => {
        const raw = parseInt((percentEl.textContent || '').trim(), 10);
        if (!Number.isFinite(raw)) return;
        percentEl.textContent = Math.max(0, Math.min(100, 100 - raw)) + '%';
        percentEl.title = '差异率（100% - 相似度）';
      });
    });

    /* “内容不同”和“正文相似”都可以进入正文差异详情。 */
    Array.from(clone.querySelectorAll('span')).forEach(sp => {
      const statusText = (sp.textContent || '').trim();
      if (statusText !== '内容不同' && statusText !== '正文相似') return;
      const row = sp.parentElement;
      if (!row || row.children.length < 3) return;

      sp.classList.add('pmm-clickable-diff');
      sp.addEventListener('click', ev => {
        ev.preventDefault();
        ev.stopPropagation();

        const possible = Array.from(row.querySelectorAll('span')).filter(s => {
          if (s === sp) return false;
          const tx = (s.textContent || '').trim();
          return tx && !/^[A-Z]{1,2}$/.test(tx) && !/^\d+%$/.test(tx);
        }).sort((a,b) => (b.textContent || '').trim().length - (a.textContent || '').trim().length);

        const name = possible.length ? (possible[0].textContent || '').trim() : '';
        if (name) openContentDiff(doc, name);
      });
    });

    const originalClose =
      header.querySelector('button') ||
      Array.from(modal.querySelectorAll('button')).find(btn => (btn.textContent || '').trim() === '关闭');

    function closePortal() {
      portal.remove();
      overlay.style.removeProperty('visibility');
      overlay.style.removeProperty('pointer-events');
      delete overlay.dataset.pmmDiffOriginal;

      try {
        if (originalClose && originalClose.isConnected) originalClose.click();
      } catch (_) {}
    }

    /* 标题 X 和底部“关闭”都关闭真正的 Vue modal。 */
    Array.from(clone.querySelectorAll('button')).forEach(btn => {
      const text = (btn.textContent || '').trim();
      const isX = !!btn.querySelector('.fa-xmark');
      if (!isX && text !== '关闭') return;
      btn.addEventListener('click', ev => {
        ev.preventDefault();
        ev.stopPropagation();
        closePortal();
      });
    });

    portal.addEventListener('click', ev => {
      if (ev.target === portal) closePortal();
    });
  }


  function ensurePresetPickerStyle(doc) {
    if (doc.getElementById('pmm-preset-picker-style')) return;
