      .pmm-preset-picker-overlay{position:absolute!important;inset:0!important;z-index:13500!important;box-sizing:border-box!important;display:flex!important;align-items:flex-start!important;justify-content:center!important;padding:max(env(safe-area-inset-top,0px),12px) 10px max(env(safe-area-inset-bottom,0px),12px)!important;background:rgba(0,0,0,.46)!important;backdrop-filter:blur(4px)!important;-webkit-backdrop-filter:blur(4px)!important;pointer-events:auto!important}
      .pmm-preset-picker-dialog{width:min(94%,430px)!important;max-height:min(78%,620px)!important;margin-top:8vh!important;display:flex!important;flex-direction:column!important;overflow:hidden!important;border:1px solid var(--pm-border,rgba(127,127,127,.22))!important;border-radius:14px!important;background:var(--pm-panel-bg,var(--pm-card-bg,#fff))!important;color:var(--pm-text-primary,#111827)!important;box-shadow:0 18px 50px rgba(0,0,0,.34)!important}
