  /* 缝合页的预设搜索窗口是 #preset-manager-main-panel 的独立子节点，
     与真正承载主题变量的 .pm-overlay 是同级，所以默认不会继承夜间主题。
     这里与正则页采用同样的方式：只复制主界面当前的 --pm-* 主题变量，
     不额外维护一套颜色。 */
  const PMM_PICKER_THEME_VARS = [
    '--pm-toolbar-bg',
    '--pm-panel-bg',
    '--pm-card-bg',
    '--pm-text-primary',
    '--pm-text-secondary',
    '--pm-border',
    '--pm-accent',
    '--pm-hover-bg',
    '--pm-selected-bg',
    '--pm-font-family',
    '--pm-font-weight',
    '--pm-text-shadow',
    '--pm-font-size',
    '--pm-line-height',
    '--pm-quote-color',
    '--pm-glass-bg',
    '--pm-glass-hover-bg',
    '--pm-floating-glass-bg',
    '--pm-floating-glass-hover-bg',
    '--pm-control-bg',
    '--pm-control-hover-bg',
    '--pm-button-bg',
    '--pm-bar-bg',
    '--pm-card-bg-translucent',
  ];

  function getPresetPickerThemeSource(doc) {
    try {
      const root = doc.getElementById('preset-manager-main-panel');
      if (!root) return null;
      const direct = Array.from(root.children || []).find(
        el => el?.classList?.contains('pm-overlay')
      );
      return direct || root.querySelector?.('.pm-overlay') || null;
    } catch (_) {
      return null;
    }
  }

  function syncPresetPickerTheme(doc, overlay) {
    if (!doc || !overlay) return false;
    const source = getPresetPickerThemeSource(doc);
    if (!source) return false;

    let computed = null;
    try {
      const view = source.ownerDocument?.defaultView || doc.defaultView || window;
      computed = view?.getComputedStyle?.(source) || null;
    } catch (_) {}

    let copied = 0;
    PMM_PICKER_THEME_VARS.forEach(name => {
      let value = '';
      try {
        value = source.style?.getPropertyValue?.(name)?.trim?.() || '';
      } catch (_) {}
      if (!value && computed) {
        try {
          value = computed.getPropertyValue(name)?.trim?.() || '';
        } catch (_) {}
      }
      if (value) {
        overlay.style.setProperty(name, value, 'important');
        copied++;
      }
    });
    return copied > 0;
  }

  function startPresetPickerThemeSync(doc, overlay) {
    if (!overlay) return;
    syncPresetPickerTheme(doc, overlay);

    const source = getPresetPickerThemeSource(doc);
    if (!source) return;

    try {
      const Observer =
        source.ownerDocument?.defaultView?.MutationObserver ||
        doc?.defaultView?.MutationObserver ||
        MutationObserver;

      const observer = new Observer(() => {
        if (!overlay.isConnected) {
          try { observer.disconnect(); } catch (_) {}
          return;
        }
        syncPresetPickerTheme(doc, overlay);
      });

      observer.observe(source, {
        attributes: true,
        attributeFilter: ['style'],
      });

      overlay.__pmmPresetPickerThemeObserver = observer;
    } catch (_) {}
  }

  function stopPresetPickerThemeSync(overlay) {
    try { overlay?.__pmmPresetPickerThemeObserver?.disconnect?.(); } catch (_) {}
  }


  function openPresetPicker(doc, select) {
    if (!doc || !select) return;
    ensurePresetPickerStyle(doc);
    const old = doc.getElementById('pmm-preset-picker-overlay');
    if (old) old.remove();
    const root = doc.getElementById('preset-manager-main-panel');
    if (!root) return;

    const opts = Array.from(select.options || []).map(o => ({value:o.value,text:(o.textContent||o.value||'').trim()}));
    const ov = doc.createElement('div'); ov.id='pmm-preset-picker-overlay'; ov.className='pmm-preset-picker-overlay';
    const box = doc.createElement('div'); box.className='pmm-preset-picker-dialog';
    const head = doc.createElement('div'); head.className='pmm-preset-picker-head';
    const input = doc.createElement('input'); input.type='search'; input.className='pmm-preset-picker-input'; input.placeholder='搜索预设…'; input.autocomplete='off'; input.autocapitalize='off'; input.spellcheck=false;
    const close = doc.createElement('button'); close.type='button'; close.className='pmm-preset-picker-close'; close.innerHTML='<i class="fa-solid fa-xmark"></i>';
    const list = doc.createElement('div'); list.className='pmm-preset-picker-list';

    const shut = () => { stopPresetPickerThemeSync(ov); if (ov.parentNode) ov.remove(); };
    const choose = value => {
      if (!select.isConnected) return shut();
      select.value = value;
      try {
        const Ev = doc.defaultView?.Event || Event;
        select.dispatchEvent(new Ev('change',{bubbles:true}));
      } catch (_) {}
      shut();
    };
    const render = () => {
      const q = input.value.trim().toLocaleLowerCase();
      const rows = q ? opts.filter(x => x.text.toLocaleLowerCase().includes(q)) : opts;
      list.replaceChildren();
      if (!rows.length) {
        const e = doc.createElement('div'); e.className='pmm-preset-picker-empty'; e.textContent='没有找到这个预设'; list.appendChild(e); return;
      }
      rows.forEach(x => {
        const b = doc.createElement('button'); b.type='button'; b.className='pmm-preset-picker-item'+(x.value===select.value?' is-current':''); b.textContent=x.text;
        b.addEventListener('click',()=>choose(x.value)); list.appendChild(b);
