  function newId(modules) {
    try {
      if (modules?.utils?.uuidv4) return modules.utils.uuidv4();
    } catch (_) {}
    try {
      if (crypto?.randomUUID) return crypto.randomUUID();
    } catch (_) {}
    return 'pmrx-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
  }

  async function getModules() {
    if (moduleCache) return moduleCache;

    /*
      1.3.1 修复：不再从脚本沙箱里 dynamic import('/scripts/...')。
      某些酒馆脚本运行器会把插件放进 iframe/srcdoc，导致这些绝对模块路径
      在那个执行上下文里加载失败。

      SillyTavern 官方已经把 getPresetManager / uuidv4 / extensionSettings /
      saveSettingsDebounced 暴露在 SillyTavern.getContext() 中，直接复用主页面
      已经加载好的 API，更稳定，也不会重复加载 Regex 模块。
    */
    try {
      const host = topWin || window;
      const ctx = host.SillyTavern?.getContext?.();

      if (!ctx || typeof ctx.getPresetManager !== 'function') {
        throw new Error('SillyTavern.getContext().getPresetManager 不可用');
      }

      const allowPresetScriptsCompat = (apiId, presetName) => {
        if (!apiId || !presetName) return;

        const settings = ctx.extensionSettings;
        if (!settings || typeof settings !== 'object') return;

        if (!settings.preset_allowed_regex || typeof settings.preset_allowed_regex !== 'object') {
          settings.preset_allowed_regex = {};
        }
        if (!Array.isArray(settings.preset_allowed_regex[apiId])) {
          settings.preset_allowed_regex[apiId] = [];
        }
        if (!settings.preset_allowed_regex[apiId].includes(presetName)) {
          settings.preset_allowed_regex[apiId].push(presetName);
          try { ctx.saveSettingsDebounced?.(); } catch (_) {}
        }
      };

      moduleCache = {
        context: ctx,
        getPresetManager: ctx.getPresetManager,
        regex: { allowPresetScripts: allowPresetScriptsCompat },
        utils: { uuidv4: ctx.uuidv4 },
      };
