        return false;
      }

      await ctx.eventSource.emit(eventType);
      state.dirtyPresets.delete(currentName);
      return true;
    } catch (error) {
      console.warn('[预设工坊][Preset Regex] 原生 Regex 列表即时刷新失败，将在关闭窗口时再尝试', error);
      return false;
    }
  }

  async function flushNativePresetRegexUI() {
    if (!state.dirtyPresets.size) return;
    try {
      const modules = await getModules();
      await refreshNativePresetRegexUI(modules, [...state.dirtyPresets]);
    } catch (error) {
      console.warn('[预设工坊][Preset Regex] 关闭时刷新原生 Regex 列表失败', error);
    }
  }

  function pushHistory(entry) {
    state.history.push(entry);
    /* 手机内存安全：只保留最近 10 次操作 */
    if (state.history.length > 10) {
      state.history.splice(0, state.history.length - 10);
    }
  }

  async function undoLastTransfer(doc) {
    if (!state.history.length) {
      tip(doc, '目前没有可以撤销的操作');
      return;
    }

    const modules = await getModules();
    const pm = getPresetManagerSafe(modules);
    const entry = state.history[state.history.length - 1];

    setBusy(doc, true);
    try {
      /* 恢复操作前两个预设的完整 preset regex 数组 */
      await writeScripts(modules, pm, entry.leftPreset, entry.leftScripts);
      if (entry.rightPreset !== entry.leftPreset) {
        await writeScripts(modules, pm, entry.rightPreset, entry.rightScripts);
      }

      state.history.pop();
      state.selectedLeft.clear();
      state.selectedRight.clear();

      state.dirtyPresets.add(entry.leftPreset);
      state.dirtyPresets.add(entry.rightPreset);

      await refreshState(doc);
      await refreshNativePresetRegexUI(modules, [entry.leftPreset, entry.rightPreset]);
      tip(doc, `已撤销：${entry.label || '上一步正则操作'} · 当前预设正则已刷新`);
    } catch (error) {
      console.error('[预设工坊][Preset Regex] 撤销失败', error);
      tip(doc, '撤销失败，原历史记录已保留，可再次尝试');
    } finally {
      setBusy(doc, false);
    }
  }

  async function refreshState(doc) {
    const modules = await getModules();
    const pm = getPresetManagerSafe(modules);
    state.presetNames = Array.isArray(pm.getAllPresets?.()) ? pm.getAllPresets() : [];

    if (!state.leftPreset || !state.presetNames.includes(state.leftPreset)) {
      state.leftPreset = pm.getSelectedPresetName?.() || state.presetNames[0] || '';
    }

    if (!state.rightPreset || !state.presetNames.includes(state.rightPreset)) {
      state.rightPreset = state.presetNames.find(x => x !== state.leftPreset) || state.leftPreset || '';
    }

    state.leftScripts = state.leftPreset ? readScripts(pm, state.leftPreset) : [];
    state.rightScripts = state.rightPreset ? readScripts(pm, state.rightPreset) : [];

    const leftIds = new Set(state.leftScripts.map(x => x.id));
    const rightIds = new Set(state.rightScripts.map(x => x.id));
    state.selectedLeft = new Set([...state.selectedLeft].filter(id => leftIds.has(id)));
    state.selectedRight = new Set([...state.selectedRight].filter(id => rightIds.has(id)));

    render(doc);
  }

  async function transfer(doc, fromSide, ids, move) {
    if (!Array.isArray(ids) || !ids.length) {
      tip(doc, '请先勾选至少一条正则');
      return;
    }

    const modules = await getModules();
    const pm = getPresetManagerSafe(modules);

    const fromName = fromSide === 'left' ? state.leftPreset : state.rightPreset;
    const toName = fromSide === 'left' ? state.rightPreset : state.leftPreset;

    if (!fromName || !toName) {
      tip(doc, '请先选择左右两个预设');
      return;
    }

    if (fromName === toName) {
      tip(doc, '左右是同一个预设，不能复制或移动到自己');
      return;
    }

    setBusy(doc, true);

    /* 操作前完整快照：这是撤销和异常回滚的依据 */
    const beforeSource = readScripts(pm, fromName);
    const beforeTarget = readScripts(pm, toName);

    try {
      const source = cloneDeep(beforeSource);
      const target = cloneDeep(beforeTarget);
      const idSet = new Set(ids);

      const chosen = source.filter(script => idSet.has(script.id));
      if (!chosen.length) {
        tip(doc, '没有找到已选择的正则');
        return;
      }

      const targetSigs = new Set(target.map(signature));
      const duplicateCount = chosen.filter(script => targetSigs.has(signature(script))).length;

      let copyDuplicates = false;
      if (duplicateCount > 0) {
        copyDuplicates = topWin.confirm(
          `目标预设已经有 ${duplicateCount} 条完全相同的正则。

确定：仍然复制重复项
取消：跳过重复项`
        );
      }

      const added = [];
      const skippedIds = new Set();

      for (const script of chosen) {
        const sig = signature(script);
        if (targetSigs.has(sig) && !copyDuplicates) {
          skippedIds.add(script.id);
          continue;
        }

        const clone = cloneDeep(script);
        clone.id = newId(modules);
        target.push(clone);
        targetSigs.add(signature(clone));
        added.push(clone);
      }

      if (!added.length && !move) {
        tip(doc, '没有需要复制的条目');
        return;
      }

      /* 先写目标。移动模式下目标写成功后，再删来源。 */
      if (added.length) {
        await writeScripts(modules, pm, toName, target);
      }

      let movedCount = 0;
      if (move) {
        const successfullyTransferredSourceIds = new Set(
          chosen.filter(script => !skippedIds.has(script.id)).map(script => script.id)
        );

        if (successfullyTransferredSourceIds.size) {
          const nextSource = source.filter(script => !successfullyTransferredSourceIds.has(script.id));
          await writeScripts(modules, pm, fromName, nextSource);
          movedCount = successfullyTransferredSourceIds.size;
        }
      }

      /* 只有整个操作成功后才写入撤销历史 */
      const actionCount = move ? movedCount : added.length;
      if (actionCount > 0) {
        const leftPreset = state.leftPreset;
        const rightPreset = state.rightPreset;

        const leftBefore = leftPreset === fromName ? beforeSource : beforeTarget;
        const rightBefore = rightPreset === fromName ? beforeSource : beforeTarget;

        pushHistory({
          leftPreset,
          rightPreset,
          leftScripts: cloneDeep(leftBefore),
          rightScripts: cloneDeep(rightBefore),
          label: `${move ? '移动' : '复制'} ${actionCount} 条 ${fromSide === 'left' ? 'A→B' : 'B→A'}`,
          time: Date.now(),
        });
      }

      if (fromSide === 'left') state.selectedLeft.clear();
      else state.selectedRight.clear();

      const changedPresets = move ? [fromName, toName] : [toName];
      changedPresets.forEach(name => state.dirtyPresets.add(name));

      await refreshState(doc);
      const nativeRefreshed = await refreshNativePresetRegexUI(modules, changedPresets);

      const skipped = chosen.length - added.length;
      const refreshText = nativeRefreshed ? ' · 当前预设正则已刷新' : '';
      if (move) {
        tip(doc, `已移动 ${movedCount} 条${skipped ? `，跳过 ${skipped} 条重复项` : ''} · 可撤销${refreshText}`);
      } else {
        tip(doc, `已复制 ${added.length} 条${skipped ? `，跳过 ${skipped} 条重复项` : ''} · 可撤销${refreshText}`);
      }
    } catch (error) {
      console.error('[预设工坊][Preset Regex] 搬运失败，开始自动回滚', error);

      /* 尽力恢复操作前状态，避免目标写成功而源删除失败造成半完成状态 */
      try {
        await writeScripts(modules, pm, fromName, beforeSource);
        await writeScripts(modules, pm, toName, beforeTarget);
        state.dirtyPresets.add(fromName);
        state.dirtyPresets.add(toName);
        await refreshNativePresetRegexUI(modules, [fromName, toName]);
        tip(doc, '操作失败，已自动恢复到操作前状态，并刷新当前预设正则');
      } catch (rollbackError) {
        console.error('[预设工坊][Preset Regex] 自动回滚失败', rollbackError);
        tip(doc, '操作失败且自动恢复未完成，请暂时不要继续搬运');
      }

      try { await refreshState(doc); } catch (_) {}
    } finally {
      setBusy(doc, false);
    }
  }

  async function deleteSingleRegex(doc, side, script) {
    const presetName = side === 'left' ? state.leftPreset : state.rightPreset;
    if (!presetName || !script?.id) {
      tip(doc, '没有找到要删除的正则');
      return;
    }

    const scriptName = script.scriptName || '未命名正则';
    const ok = topWin.confirm(
      `确定要从「${presetName}」删除这条预设正则吗？

${scriptName}

删除后仍可使用顶部“撤销”恢复。`
    );
    if (!ok) return;

    const modules = await getModules();
    const pm = getPresetManagerSafe(modules);
    setBusy(doc, true);

    const leftBefore = readScripts(pm, state.leftPreset);
    const rightBefore = readScripts(pm, state.rightPreset);

    try {
      const beforeCurrent = side === 'left' ? leftBefore : rightBefore;
      const next = beforeCurrent.filter(item => item.id !== script.id);

      if (next.length === beforeCurrent.length) {
        tip(doc, '这条正则已经不存在，列表将重新刷新');
        await refreshState(doc);
        return;
      }

      await writeScripts(modules, pm, presetName, next);

      pushHistory({
        leftPreset: state.leftPreset,
        rightPreset: state.rightPreset,
        leftScripts: cloneDeep(leftBefore),
        rightScripts: cloneDeep(rightBefore),
        label: `删除 1 条 ${side === 'left' ? 'A' : 'B'} · ${scriptName}`,
        time: Date.now(),
      });

      if (side === 'left') state.selectedLeft.delete(script.id);
      else state.selectedRight.delete(script.id);

      state.dirtyPresets.add(presetName);

      await refreshState(doc);
      const nativeRefreshed = await refreshNativePresetRegexUI(modules, [presetName]);
      tip(doc, `已删除「${scriptName}」 · 可撤销${nativeRefreshed ? ' · 当前预设正则已刷新' : ''}`);
    } catch (error) {
      console.error('[预设工坊][Preset Regex] 删除单条正则失败，尝试恢复', error);

      try {
        await writeScripts(modules, pm, state.leftPreset, leftBefore);
        if (state.rightPreset !== state.leftPreset) {
          await writeScripts(modules, pm, state.rightPreset, rightBefore);
        }
        await refreshNativePresetRegexUI(modules, [state.leftPreset, state.rightPreset]);
        tip(doc, '删除失败，已恢复到删除前状态');
      } catch (rollbackError) {
        console.error('[预设工坊][Preset Regex] 删除失败且自动恢复失败', rollbackError);
        tip(doc, '删除失败，请暂时不要继续操作正则');
      }

      try { await refreshState(doc); } catch (_) {}
    } finally {
      setBusy(doc, false);
    }
  }

  function makeOption(doc, name, selected) {
    const option = doc.createElement('option');
    option.value = name;
    option.textContent = name;
    option.selected = name === selected;
    return option;
  }


