  function openRegexPresetPicker(doc, select) {
    ensureRegexPresetPickerStyle(doc);
    const old=doc.getElementById('pmrx-preset-picker-overlay'); if(old)old.remove();
    const host=getOverlay(doc)||doc.body; if(!host)return;
    const opts=Array.from(select.options||[]).map(o=>({value:o.value,text:(o.textContent||o.value||'').trim()}));
    const ov=doc.createElement('div');ov.id='pmrx-preset-picker-overlay';ov.className='pmrx-preset-picker-overlay';
    const box=doc.createElement('div');box.className='pmrx-preset-picker-dialog';
    const head=doc.createElement('div');head.className='pmrx-preset-picker-head';
    const input=doc.createElement('input');input.type='search';input.className='pmrx-preset-picker-input';input.placeholder='搜索预设…';input.autocomplete='off';input.autocapitalize='off';input.spellcheck=false;
    const close=doc.createElement('button');close.type='button';close.className='pmrx-preset-picker-close';close.innerHTML='<i class="fa-solid fa-xmark"></i>';
    const list=doc.createElement('div');list.className='pmrx-preset-picker-list';
    const shut=()=>{if(ov.parentNode)ov.remove()};
    const choose=value=>{if(!select.isConnected)return shut();select.value=value;try{const Ev=doc.defaultView?.Event||Event;select.dispatchEvent(new Ev('change',{bubbles:true}))}catch(_){}shut()};
    const render=()=>{const q=input.value.trim().toLocaleLowerCase(),rows=q?opts.filter(x=>x.text.toLocaleLowerCase().includes(q)):opts;list.replaceChildren();if(!rows.length){const e=doc.createElement('div');e.className='pmrx-preset-picker-empty';e.textContent='没有找到这个预设';list.appendChild(e);return}rows.forEach(x=>{const b=doc.createElement('button');b.type='button';b.className='pmrx-preset-picker-item'+(x.value===select.value?' is-current':'');b.textContent=x.text;b.addEventListener('click',()=>choose(x.value));list.appendChild(b)})};
    input.addEventListener('input',render);close.addEventListener('click',shut);ov.addEventListener('click',e=>{if(e.target===ov)shut()});head.append(input,close);box.append(head,list);ov.appendChild(box);host.appendChild(ov);render();
    setTimeout(()=>{try{input.focus({preventScroll:true})}catch(_){try{input.focus()}catch(_){}};const cur=list.querySelector('.is-current');if(cur)try{cur.scrollIntoView({block:'center'})}catch(_){}},30);
  }

  function renderPane(doc, side) {
    const isLeft = side === 'left';
    const pane = doc.createElement('div');
    pane.className = `pmrx-pane ${side}`;

    const scripts = isLeft ? state.leftScripts : state.rightScripts;
    const selected = isLeft ? state.selectedLeft : state.selectedRight;
    const presetName = isLeft ? state.leftPreset : state.rightPreset;

    const head = doc.createElement('div');
    head.className = 'pmrx-pane-head';

    const badge = doc.createElement('div');
    badge.className = `pmrx-side-badge ${isLeft ? 'left' : 'right'}`;
    badge.textContent = isLeft ? 'A' : 'B';

    const select = doc.createElement('select');
    select.className = 'pmrx-preset-select';
    state.presetNames.forEach(name => select.appendChild(makeOption(doc, name, presetName)));
    select.addEventListener('change', async () => {
      if (isLeft) {
        state.leftPreset = select.value;
        state.selectedLeft.clear();
      } else {
        state.rightPreset = select.value;
        state.selectedRight.clear();
      }
      await refreshState(doc);
    });

    ensureRegexPresetPickerStyle(doc);
    const presetSearch = doc.createElement('button');
    presetSearch.type = 'button';
    presetSearch.className = 'pmrx-preset-search';
    presetSearch.title = '搜索预设';
    presetSearch.setAttribute('aria-label', '搜索预设');
    presetSearch.innerHTML = '<i class="fa-solid fa-magnifying-glass"></i>';
    presetSearch.addEventListener('click', ev => {
      ev.preventDefault();
      ev.stopPropagation();
      openRegexPresetPicker(doc, select);
    });

    const count = doc.createElement('div');
    count.className = 'pmrx-count';
    count.textContent = `${scripts.length} 条`;

    const selectAll = doc.createElement('button');
    selectAll.type = 'button';
    selectAll.className = 'pmrx-select-all';
    selectAll.title = selected.size === scripts.length && scripts.length ? '取消全选' : '全选';
    selectAll.innerHTML = `<i class="fa-solid ${selected.size === scripts.length && scripts.length ? 'fa-minus' : 'fa-check-double'}"></i>`;
    selectAll.addEventListener('click', () => {
      if (selected.size === scripts.length && scripts.length) {
        selected.clear();
      } else {
        scripts.forEach(script => script.id && selected.add(script.id));
      }
      render(doc);
    });

    head.append(badge, select, presetSearch, count, selectAll);

    const list = doc.createElement('div');
    list.className = 'pmrx-list';

    if (!scripts.length) {
      const empty = doc.createElement('div');
      empty.className = 'pmrx-empty';
      empty.innerHTML = '这个预设目前没有绑定正则<br>可以从另一侧复制或移动过来';
      list.appendChild(empty);
    } else {
      scripts.forEach((script, index) => {
        const card = doc.createElement('div');
        card.className = 'pmrx-card' + (selected.has(script.id) ? ' is-selected' : '');

        const check = doc.createElement('input');
        check.type = 'checkbox';
        check.className = 'pmrx-check';
        check.checked = selected.has(script.id);
        check.addEventListener('change', () => {
          if (check.checked) selected.add(script.id);
          else selected.delete(script.id);
          card.classList.toggle('is-selected', check.checked);
        });

        const main = doc.createElement('div');
        main.className = 'pmrx-main';

        const nameRow = doc.createElement('div');
        nameRow.className = 'pmrx-name-row';

        const name = doc.createElement('div');
        name.className = 'pmrx-name';
        name.textContent = script.scriptName || `未命名正则 ${index + 1}`;

        const enabled = doc.createElement('div');
        enabled.className = 'pmrx-state ' + (script.disabled ? 'off' : 'on');
        enabled.textContent = script.disabled ? '关闭' : '开启';

        const preview = doc.createElement('div');
        preview.className = 'pmrx-preview';
        preview.textContent = script.findRegex || '（没有 Find Regex）';

        nameRow.append(name);
        main.append(nameRow, preview);

        const copy = doc.createElement('button');
        copy.type = 'button';
        copy.className = 'pmrx-mini-btn copy';
        copy.title = isLeft ? '复制到 B（原预设保留）' : '复制到 A（原预设保留）';
        copy.innerHTML = `
          <span class="pmrx-mini-copy-direction">
            <i class="fa-solid fa-plus"></i>
            <i class="fa-solid ${isLeft ? 'fa-arrow-down' : 'fa-arrow-up'}"></i>
          </span>`;
        copy.addEventListener('click', () => transfer(doc, side, [script.id], false));

        const remove = doc.createElement('button');
        remove.type = 'button';
        remove.className = 'pmrx-mini-btn delete';
        remove.title = '删除这条正则';
        remove.innerHTML = `<i class="fa-solid fa-trash"></i>`;
        remove.addEventListener('click', () => deleteSingleRegex(doc, side, script));

        card.append(check, main, enabled, copy, remove);
        list.appendChild(card);
      });
    }

    pane.append(head, list);
    return pane;
  }

  function renderTransferBar(doc) {
    const bar = doc.createElement('div');
    bar.className = 'pmrx-transfer-bar';

    const defs = [
      { side: 'left', move: false, cls: 'copy', icon: 'fa-copy', label: 'A→B 复制' },
      { side: 'left', move: true, cls: 'move', icon: 'fa-arrow-down', label: 'A→B 移动' },
      { side: 'right', move: false, cls: 'copy', icon: 'fa-copy', label: 'B→A 复制' },
      { side: 'right', move: true, cls: 'move', icon: 'fa-arrow-up', label: 'B→A 移动' },
    ];

    defs.forEach(def => {
      const btn = doc.createElement('button');
      btn.type = 'button';
      btn.className = `pmrx-transfer-btn ${def.cls}`;

      /* 1.3.21：只有“复制”按钮在复制图标右侧追加方向箭头。
         A→B = 向下，B→A = 向上；移动按钮保持原样。 */
      if (!def.move) {
        const dirIcon = def.side === 'left' ? 'fa-arrow-down' : 'fa-arrow-up';
        btn.innerHTML = `<span class="pmrx-copy-icon-pair"><i class="fa-solid fa-copy"></i><i class="fa-solid ${dirIcon} pmrx-copy-dir"></i></span><span>${def.label}</span>`;
      } else {
        btn.innerHTML = `<i class="fa-solid ${def.icon}"></i><span>${def.label}</span>`;
      }

      btn.addEventListener('click', () => {
        const ids = [...(def.side === 'left' ? state.selectedLeft : state.selectedRight)];
        transfer(doc, def.side, ids, def.move);
      });
      bar.appendChild(btn);
    });

