      DOC.addEventListener('pointermove', move, { capture:true, passive:false });
      DOC.addEventListener('pointerup', end, true);
      DOC.addEventListener('pointercancel', end, true);
    }
  }

  function buildCard() {
    const panel = DOC.createElement('section');
    panel.id = 'pmm-mobile-layout-card';
    let themeMode = '';
    try { themeMode = String(TOP.localStorage?.getItem('preset-manager-theme-mode') || ''); } catch (_) {}
    panel.dataset.pmmLayoutTheme = themeMode === 'dark' ? 'dark' : 'light';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-modal', 'false');
    panel.setAttribute('aria-label', isMobile() ? '手机版布局调节' : '电脑版布局调节');
    panel.innerHTML = `
      <div class="pmm-layout-card__shine"></div>
      <header class="pmm-layout-card__header">
        <button type="button" class="pmm-layout-icon-btn" data-pmm-layout-close aria-label="关闭">×</button>
      </header>
      <div class="pmm-layout-card__body"></div>
      <footer class="pmm-layout-card__footer">
        <button type="button" class="pmm-layout-soft-btn" data-pmm-layout-reset>恢复全部默认</button>
        <button type="button" class="pmm-layout-done-btn" data-pmm-layout-done>完成</button>
      </footer>`;
    const body = panel.querySelector('.pmm-layout-card__body');
    for (const control of currentControls()) body.appendChild(makeControl(control));
    panel.querySelector('[data-pmm-layout-close]').addEventListener('click', closeCard);
    panel.querySelector('[data-pmm-layout-done]').addEventListener('click', closeCard);
    panel.querySelector('[data-pmm-layout-reset]').addEventListener('click', () => {
      const key = isMobile() ? 'mobile' : 'desktop';
      state[key] = makeLayoutState();
      applyState(true);
    });
    const header = panel.querySelector('.pmm-layout-card__header');
    if ('PointerEvent' in TOP) header.addEventListener('pointerdown', beginCardDrag);
    else header.addEventListener('touchstart', beginCardDrag, { passive:false });
    return panel;
  }

  function closeCard() {
    activeCardDragCleanup?.();
    if (card) {
      const removing = card;
      card = null;
      removing.classList.remove('pmm-layout-card--open');
      setTimeout(() => removing.remove(), 180);
    }
    trigger?.classList.remove('pmm-layout-trigger--open');
    trigger?.setAttribute('aria-expanded', 'false');
  }

  function openCard() {
    if (!root || card) return;
    card = buildCard();
    root.appendChild(card);
    updateOutputs();
    trigger?.classList.add('pmm-layout-trigger--open');
    trigger?.setAttribute('aria-expanded', 'true');
    VIEW.requestAnimationFrame?.(() => card?.classList.add('pmm-layout-card--open'));
  }

  function onTriggerClick(event) {
    event.preventDefault();
    event.stopPropagation();
    if (card) return closeCard();
    openCard();
  }

  function ensureTrigger(sideRoot) {
    if (!sideRoot) return;
    const existing = sideRoot.querySelector(':scope > .pmm-layout-trigger');
    if (existing) {
      trigger = existing;
      const glyph = trigger.querySelector('.pmm-layout-trigger__arrow > span');
      const nextGlyph = isMobile() ? '›' : '⌄';
      if (glyph && glyph.textContent !== nextGlyph) glyph.textContent = nextGlyph;
      trigger.setAttribute('aria-label', isMobile() ? '展开手机布局设置' : '展开电脑布局设置');
      return;
    }
    trigger = DOC.createElement('button');
    trigger.type = 'button';
    trigger.className = 'pmm-layout-trigger';
    trigger.setAttribute('aria-label', isMobile() ? '展开手机布局设置' : '展开电脑布局设置');
    trigger.setAttribute('aria-expanded', 'false');
    trigger.innerHTML = `<span class="pmm-layout-trigger__arrow"><span aria-hidden="true">${isMobile() ? '›' : '⌄'}</span></span>`;
    trigger.addEventListener('click', onTriggerClick);
    sideRoot.appendChild(trigger);
  }

  function syncTriggerVisibility(sideRoot) {
    if (!sideRoot || !trigger) return;
    const expandedPanel = sideRoot.querySelector(':scope > .side-panel-content');
    const expandedStyles = expandedPanel ? VIEW.getComputedStyle?.(expandedPanel) : null;
    const hasVisibleExpandedPanel = Boolean(expandedPanel)
      && expandedStyles?.display !== 'none'
      && expandedStyles?.visibility !== 'hidden'
      && expandedPanel.hidden !== true;
    const toolbarCollapsed = !isMobile() && !hasVisibleExpandedPanel;
    trigger.classList.toggle('pmm-layout-trigger--toolbar-collapsed', toolbarCollapsed);
    trigger.setAttribute('aria-hidden', toolbarCollapsed ? 'true' : 'false');
    trigger.tabIndex = toolbarCollapsed ? -1 : 0;
    if (toolbarCollapsed && card) closeCard();
  }

  function resizeFromPoint(clientX, clientY, splitContainer, edge) {
    const rect = splitContainer.getBoundingClientRect();
    const styles = VIEW.getComputedStyle?.(splitContainer);
    let ratio;
    if (isMobile()) {
      const rootStyles = VIEW.getComputedStyle?.(root);
      const toolbar = parseFloat(rootStyles?.getPropertyValue('--pmm-toolbar-h')) || 40;
      const gap = parseFloat(styles?.rowGap || styles?.gap || rootStyles?.getPropertyValue('--pmm-gap')) || 6;
      const available = Math.max(1, rect.height - toolbar - gap * 2);
      ratio = ((clientY - rect.top - gap - toolbar / 2) / available) * 100;
    } else {
      const toolbarNode = splitContainer.querySelector(':scope > .pm-main-wrapper > .side-panel-root');
      const toolbar = toolbarNode?.getBoundingClientRect?.().width || 72;
      const gap = parseFloat(styles?.columnGap || styles?.gap || '0') || 6;
      const available = Math.max(1, rect.width - toolbar - gap * 2);
      const adjustedX = edge === 'right'
        ? clientX - rect.left - toolbar - gap * 2
        : clientX - rect.left;
      ratio = adjustedX / available * 100;
    }
    const current = currentState();
    current.values.splitRatio = Math.round(clamp('splitRatio', ratio));
    current.customized.splitRatio = true;
    applyState(true);
  }

  function resetSplitRatio() {
    const current = currentState();
    current.values.splitRatio = DEFAULTS.splitRatio;
    current.customized.splitRatio = false;
    applyState(true);
  }

  function beginSplitResize(event) {
    const splitContainer = event.currentTarget.closest(MODE_SELECTOR);
    if (!splitContainer) return;
    const handle = event.currentTarget;
    const edge = ['top', 'bottom', 'left', 'right'].find(name => handle.classList.contains(`pmm-split-handle--${name}`));
    const isPrimaryHandle = edge === 'top' || edge === 'left';
    const mobileResize = edge === 'top' || edge === 'bottom';
    const firstPoint = event.touches?.[0] || event;
    const startX = Number(firstPoint.clientX);
    const startY = Number(firstPoint.clientY);
    const startAt = Date.now();
    let moved = false;
    event.preventDefault();
    event.stopPropagation();
    activeResizeCleanup?.();
    const move = moveEvent => {
      const point = moveEvent.touches?.[0] || moveEvent;
      if (!Number.isFinite(point.clientX) || !Number.isFinite(point.clientY)) return;
      moveEvent.preventDefault?.();
      if (!Number.isFinite(startX) || !Number.isFinite(startY)) return;
      if (!moved) {
        const distance = mobileResize ? Math.abs(point.clientY - startY) : Math.abs(point.clientX - startX);
        if (distance <= 7) return;
        moved = true;
        root.classList.add('pmm-layout-resizing');
      }
      resizeFromPoint(point.clientX, point.clientY, splitContainer, edge);
    };
    const end = endEvent => {
      root?.classList.remove('pmm-layout-resizing');
      DOC.removeEventListener('pointermove', move, true);
      DOC.removeEventListener('pointerup', end, true);
      DOC.removeEventListener('pointercancel', end, true);
      DOC.removeEventListener('touchmove', move, true);
      DOC.removeEventListener('touchend', end, true);
      DOC.removeEventListener('touchcancel', end, true);
      activeResizeCleanup = null;
      const now = Date.now();
      const cancelled = String(endEvent?.type || '').includes('cancel');
      if (!cancelled && isPrimaryHandle && !moved && now - startAt < 360) {
        const previousTap = Number(handle.dataset.pmmLastTapAt || 0);
        if (previousTap && now - previousTap < 380) {
          delete handle.dataset.pmmLastTapAt;
          resetSplitRatio();
        } else {
          handle.dataset.pmmLastTapAt = String(now);
        }
      } else {
        delete handle.dataset.pmmLastTapAt;
      }
    };
    activeResizeCleanup = () => end({ type:'pmm-cancel' });
    if (event.type.startsWith('touch')) {
      DOC.addEventListener('touchmove', move, { capture:true, passive:false });
      DOC.addEventListener('touchend', end, true);
      DOC.addEventListener('touchcancel', end, true);
    } else {
      DOC.addEventListener('pointermove', move, { capture:true, passive:false });
      DOC.addEventListener('pointerup', end, true);
      DOC.addEventListener('pointercancel', end, true);
    }
  }

  function makeHandle(edge) {
    const handle = DOC.createElement('button');
    handle.type = 'button';
    handle.className = `pmm-split-handle pmm-split-handle--${edge}`;
    const labels = {
      top:'拖动调整上方卡片高度，双击恢复默认比例',
      bottom:'拖动调整下方卡片高度',
      left:'拖动调整左侧卡片宽度，双击恢复默认比例',
      right:'拖动调整右侧卡片宽度',
    };
    handle.setAttribute('aria-label', labels[edge]);
    handle.innerHTML = '<span></span><span></span><span></span>';
    if ('PointerEvent' in TOP) handle.addEventListener('pointerdown', beginSplitResize);
    else handle.addEventListener('touchstart', beginSplitResize, { passive:false });
    return handle;
  }

  function ensureHandles(splitContainer) {
    if (!splitContainer) return;
    const edges = isMobile() ? ['top', 'bottom'] : ['left', 'right'];
    splitContainer.querySelectorAll(':scope > .pmm-split-handle').forEach(handle => {
      if (!edges.some(edge => handle.classList.contains(`pmm-split-handle--${edge}`))) handle.remove();
    });
    for (const edge of edges) {
      if (!splitContainer.querySelector(`:scope > .pmm-split-handle--${edge}`)) splitContainer.appendChild(makeHandle(edge));
    }
  }

  function watchContainer(nextContainer) {
    if (container === nextContainer) return;
    modeObserver?.disconnect();
    container = nextContainer;
    if (!container) return;
    modeObserver = new MutationObserverCtor(scheduleSync);
    modeObserver.observe(container, { attributes:true, attributeFilter:['class'] });
  }

  function watchToolbar(nextToolbar) {
    if (toolbarRoot === nextToolbar) return;
    toolbarObserver?.disconnect();
    toolbarRoot = nextToolbar;
    if (!toolbarRoot) return;
    toolbarObserver = new MutationObserverCtor(scheduleSync);
    toolbarObserver.observe(toolbarRoot, {
      attributes:true,
      attributeFilter:['style', 'class'],
      childList:true,
      subtree:true,
    });
  }

  function sync() {
    scheduledFrame = 0;
    const nextRoot = DOC.querySelector('#preset-manager-main-panel');
    const mobileNow = isMobile();
    if (!nextRoot) {
      if (root && root !== nextRoot) closeCard();
      root?.classList.remove('pmm-mobile-layout-enabled');
      root = nextRoot;
      currentMobileLayout = null;
      watchContainer(null);
      watchToolbar(null);
      resizeObserver?.disconnect();
      resizeObserver = null;
      return;
    }
    const layoutChanged = currentMobileLayout !== null && currentMobileLayout !== mobileNow;
    if (layoutChanged) closeCard();
    currentMobileLayout = mobileNow;
    if (root !== nextRoot) {
      closeCard();
      resizeObserver?.disconnect();
      presetWidthMaxOffset = PRESET_WIDTH_MAX;
      root = nextRoot;
      resizeObserver = typeof ResizeObserverCtor === 'function' ? new ResizeObserverCtor(() => {
        refreshHeaderWrapping();
        keepCardInBounds();
      }) : null;
      resizeObserver?.observe(root);
    }
    const nextContainer = root.querySelector('.pm-panel-container');
    watchContainer(nextContainer);
    const sideRoot = root.querySelector('.side-panel-root');
    ensureTrigger(sideRoot);
    watchToolbar(sideRoot);
    syncTriggerVisibility(sideRoot);
    if (!mobileNow && nextContainer?.classList.contains('pm-panel-container--sidebar-collapsed') && card) closeCard();
    const splitContainer = root.querySelector(MODE_SELECTOR);
    if (splitContainer) ensureHandles(splitContainer);
    else container?.querySelectorAll(':scope > .pmm-split-handle').forEach(handle => handle.remove());
    applyState(false);
  }

  function scheduleSync() {
    if (scheduledFrame) return;
    scheduledFrame = VIEW.requestAnimationFrame ? VIEW.requestAnimationFrame(sync) : VIEW.setTimeout(sync, 16);
  }

  function onOutsidePointer(event) {
    if (!card) return;
    if (card.contains(event.target) || trigger?.contains(event.target)) return;
    closeCard();
  }

