      if (name) notify('success', `预设已切换：${abbreviatePresetName(name)}`);
    });
  }

  function bindAutoCollapseOnEdit(root) {
    const action = root?.querySelector?.('.panel-action .fa-edit')?.closest?.('.panel-action');
    if (!action || action.dataset.pmmEditCollapseBound === '1') return;
    action.dataset.pmmEditCollapseBound = '1';
    action.addEventListener('click', () => {
      if (!isMobile()) return;
      /* 先让工坊原有的铅笔事件完成，再只收起悬浮工具栏。 */
      SELF.setTimeout(() => root.classList.remove('pmm-floating-mobile-open'), 0);
    });
  }

  function setDock(root, dock, top, persist = false) {
    if (!root) return;
    const view = root.ownerDocument?.defaultView || SELF;
    const nextDock = dock === 'left' ? 'left' : 'right';
    const maximumTop = Math.max(12, (view.innerHeight || 720) - 52);
    const nextTop = clamp(top, 12, maximumTop);
    root.classList.toggle('pmm-floating-dock-left', nextDock === 'left');
    root.classList.toggle('pmm-floating-dock-right', nextDock === 'right');
    const nextTopValue = `${nextTop}px`;
    const nextWidthValue = `${readFloatingWidth(view)}px`;
    if (root.style.getPropertyValue('--pmm-mobile-floating-top') !== nextTopValue) {
      root.style.setProperty('--pmm-mobile-floating-top', nextTopValue);
    }
    if (root.style.getPropertyValue('--pmm-mobile-floating-width') !== nextWidthValue) {
      root.style.setProperty('--pmm-mobile-floating-width', nextWidthValue);
    }
    root.dataset.pmmFloatingDock = nextDock;
    updateEdgeArrow(root);
    if (persist) savePosition(nextDock, nextTop);
  }

  function updateEdgeArrow(root) {
    const icon = root?.querySelector(':scope > .edge-tab i');
    if (!icon) return;
    const left = root.classList.contains('pmm-floating-dock-left');
    icon.classList.remove('fa-chevron-left', 'fa-chevron-right');
    icon.classList.add(left ? 'fa-chevron-right' : 'fa-chevron-left');
  }

  function panelExpanded(root) {
    if (root?.classList.contains('pmm-floating-mobile')) {
      return root.classList.contains('pmm-floating-mobile-open');
    }
    const panel = root?.querySelector(':scope > .panel-wrapper');
    return Boolean(panel && SELF.getComputedStyle(panel).display !== 'none');
  }

  function triggerNativeToggle(root, point) {
    if (root?.classList.contains('pmm-floating-mobile')) {
      root.classList.toggle('pmm-floating-mobile-open');
      return;
    }
    const target = panelExpanded(root)
      ? root.querySelector(':scope > .panel-wrapper .panel-collapse')
      : root.querySelector(':scope > .edge-tab');
    if (!target) return;
    if (target.matches('.panel-collapse')) {
      target.dispatchEvent(new MouseEvent('click', { bubbles:true, cancelable:true, view:SELF }));
      return;
    }
    const init = {
      bubbles:true,
      cancelable:true,
      view:SELF,
      button:0,
      buttons:1,
      clientX:Number(point?.clientX || 0),
      clientY:Number(point?.clientY || 0),
    };
    target.dispatchEvent(new MouseEvent('mousedown', init));
    const owner = target.ownerDocument || DOC;
    owner.dispatchEvent(new MouseEvent('mouseup', { ...init, buttons:0 }));
  }

  function endActiveDrag() {
    try { activeDragCleanup?.(); } catch (_) {}
    activeDragCleanup = null;
  }

  function beginMobileDrag(event, root) {
    if (!isMobile() || !root) return;
    if (event.button != null && event.button !== 0) return;
    const collapseHandle = event.target?.closest?.('.panel-collapse');
    const interactive = event.target?.closest?.('button,select,input,option,.panel-action,.panel-section,.pmm-preset-batch-trigger');
    if (interactive && !collapseHandle) return;
    const point = event.touches?.[0] || event;
    const startX = Number(point.clientX);
    const startY = Number(point.clientY);
    if (!Number.isFinite(startX) || !Number.isFinite(startY)) return;
    const startTop = parseFloat(root.style.getPropertyValue('--pmm-mobile-floating-top')) || root.getBoundingClientRect().top;
    const dragDocument = root.ownerDocument || DOC;
    const dragView = dragDocument.defaultView || SELF;
    let moved = false;
    let nextDock = root.dataset.pmmFloatingDock === 'left' ? 'left' : 'right';
    let nextTop = startTop;
    let lastPoint = { clientX:startX, clientY:startY };

    endActiveDrag();
    root.classList.add('pmm-floating-dragging');
    try { event.currentTarget?.setPointerCapture?.(event.pointerId); } catch (_) {}

    const move = moveEvent => {
      const movePoint = moveEvent.touches?.[0] || moveEvent;
      if (!Number.isFinite(Number(movePoint.clientX)) || !Number.isFinite(Number(movePoint.clientY))) return;
      const dx = Number(movePoint.clientX) - startX;
      const dy = Number(movePoint.clientY) - startY;
      if (!moved && Math.hypot(dx, dy) > 7) moved = true;
      if (!moved) return;
      moveEvent.preventDefault?.();
      moveEvent.stopPropagation?.();
      lastPoint = { clientX:Number(movePoint.clientX), clientY:Number(movePoint.clientY) };
      nextDock = lastPoint.clientX < (dragView.innerWidth || 768) / 2 ? 'left' : 'right';
      nextTop = startTop + dy;
      setDock(root, nextDock, nextTop, false);
    };
    const end = endEvent => {
      root.classList.remove('pmm-floating-dragging');
      dragDocument.removeEventListener('pointermove', move, true);
      dragDocument.removeEventListener('pointerup', end, true);
      dragDocument.removeEventListener('pointercancel', cancel, true);
      dragDocument.removeEventListener('touchmove', move, true);
      dragDocument.removeEventListener('touchend', end, true);
      dragDocument.removeEventListener('touchcancel', cancel, true);
      activeDragCleanup = null;
      if (moved) {
        root.dataset.pmmSuppressFloatingClickUntil = String(Date.now() + 420);
        setDock(root, nextDock, nextTop, true);
      }
    };
    const cancel = () => {
      root.classList.remove('pmm-floating-dragging');
      dragDocument.removeEventListener('pointermove', move, true);
      dragDocument.removeEventListener('pointerup', end, true);
      dragDocument.removeEventListener('pointercancel', cancel, true);
      dragDocument.removeEventListener('touchmove', move, true);
      dragDocument.removeEventListener('touchend', end, true);
      dragDocument.removeEventListener('touchcancel', cancel, true);
      activeDragCleanup = null;
    };
    activeDragCleanup = cancel;
    if (event.type.startsWith('touch')) {
      dragDocument.addEventListener('touchmove', move, { capture:true, passive:false });
      dragDocument.addEventListener('touchend', end, true);
      dragDocument.addEventListener('touchcancel', cancel, true);
    } else {
      dragDocument.addEventListener('pointermove', move, { capture:true, passive:false });
      dragDocument.addEventListener('pointerup', end, true);
      dragDocument.addEventListener('pointercancel', cancel, true);
    }
  }

  function bindMobileDrag(root) {
    const targets = [
      root.querySelector(':scope > .edge-tab'),
      root.querySelector(':scope > .panel-wrapper > .panel-header'),
    ].filter(Boolean);
    for (const target of targets) {
      if (target.dataset.pmmFloatingDragBound === '1') continue;
      target.dataset.pmmFloatingDragBound = '1';
      if ('PointerEvent' in SELF) target.addEventListener('pointerdown', event => beginMobileDrag(event, root), true);
      /* iOS Safari 虽支持 PointerEvent，但贴边元素有时不会连续送达 pointermove；触摸事件作为拖动兜底。 */
      target.addEventListener('touchstart', event => beginMobileDrag(event, root), { capture:true, passive:false });
    }
    const edge = root.querySelector(':scope > .edge-tab');
    if (edge && edge.dataset.pmmFloatingClickBound !== '1') {
      edge.dataset.pmmFloatingClickBound = '1';
      edge.addEventListener('click', event => {
        if (!isMobile()) return;
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        if (Date.now() < Number(root.dataset.pmmSuppressFloatingClickUntil || 0)) return;
        root.classList.add('pmm-floating-mobile-open');
      }, true);
    }
    const collapse = root.querySelector(':scope > .panel-wrapper .panel-collapse');
    if (collapse && collapse.dataset.pmmFloatingCollapseBound !== '1') {
      collapse.dataset.pmmFloatingCollapseBound = '1';
      collapse.addEventListener('click', event => {
        if (!isMobile()) return;
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        if (Date.now() < Number(root.dataset.pmmSuppressFloatingClickUntil || 0)) return;
        root.classList.remove('pmm-floating-mobile-open');
      }, true);
    }
  }

  function syncSelectOptions(root) {
    const manager = getPresetManagerSafe();
    const select = getPresetSelect(root);
    if (!manager || !select) return;
    let names = [];
    try { names = Array.from(manager.getAllPresets?.() || []).map(String); } catch (_) {}
    if (!names.length) return;
    const currentOptions = Array.from(select.options).map(option => option.value);
    if (currentOptions.length === names.length && currentOptions.every((name, index) => name === names[index])) return;
    const selected = String(manager.getSelectedPresetName?.() || select.value || '');
    select.replaceChildren(...names.map(name => {
      const option = select.ownerDocument.createElement('option');
      option.value = name;
      option.textContent = name;
      return option;
    }));
    select.value = names.includes(selected) ? selected : names[0];
  }

  function repairPresetSelectState(root, manager, preferredName, deletedNames = new Set()) {
    const selects = [];
    const add = select => {
      const element = select?.jquery ? select[0] : select;
      if (element?.tagName === 'SELECT' && !selects.includes(element)) selects.push(element);
    };
    add(manager?.select);
    add(getPresetSelect(root));
    for (const currentDocument of documents()) {
      const found = currentDocument.querySelectorAll?.('select[data-preset-manager-for~="openai"],select[data-preset-manager-for*="openai"]') || [];
      for (const select of found) add(select);
    }
    for (const select of selects) {
      for (const option of Array.from(select.options || [])) {
        const name = String(option.textContent || option.label || '').trim();
        if (!name || deletedNames.has(name)) option.remove();
      }
      const options = Array.from(select.options || []);
      const chosen = options.find(option => String(option.textContent || option.label || '').trim() === preferredName)
        || options.find(option => !option.disabled)
        || options[0];
      if (!chosen) continue;
      for (const option of options) {
        option.selected = option === chosen;
        if (option === chosen) option.setAttribute('selected', 'selected');
        else option.removeAttribute('selected');
      }
      select.value = chosen.value;
    }
  }

  function closeBatchDialog() {
    const removing = batchDialog;
    try { batchViewportCleanup?.(); } catch (_) {}
    batchViewportCleanup = null;
    batchDialog = null;
    batchDialogDocument = null;
    removing?.remove();
  }

  function bindBatchToVisibleViewport(overlay, ownerDocument) {
    if (!isMobile()) return;
    const view = ownerDocument?.defaultView || TOP || SELF;
    const viewport = view.visualViewport;
    const update = () => {
      if (!overlay?.isConnected) return;
      const left = Number(view.scrollX || view.pageXOffset || 0) + Number(viewport?.offsetLeft || 0);
      const top = Number(view.scrollY || view.pageYOffset || 0) + Number(viewport?.offsetTop || 0);
      const width = Math.max(1, Number(viewport?.width || view.innerWidth || ownerDocument.documentElement?.clientWidth || 1));
      const height = Math.max(1, Number(viewport?.height || view.innerHeight || ownerDocument.documentElement?.clientHeight || 1));
      overlay.style.position = 'absolute';
      overlay.style.inset = 'auto';
      overlay.style.left = `${left}px`;
      overlay.style.top = `${top}px`;
      overlay.style.width = `${width}px`;
      overlay.style.height = `${height}px`;
      overlay.style.setProperty('--pmm-batch-visible-height', `${height}px`);
    };
    const scheduleUpdate = () => view.requestAnimationFrame?.(update) || view.setTimeout?.(update, 0);
    update();
    viewport?.addEventListener?.('resize', scheduleUpdate, { passive:true });
    viewport?.addEventListener?.('scroll', scheduleUpdate, { passive:true });
    view.addEventListener?.('resize', scheduleUpdate, { passive:true });
    view.addEventListener?.('scroll', scheduleUpdate, { passive:true });
    batchViewportCleanup = () => {
      viewport?.removeEventListener?.('resize', scheduleUpdate);
      viewport?.removeEventListener?.('scroll', scheduleUpdate);
      view.removeEventListener?.('resize', scheduleUpdate);
      view.removeEventListener?.('scroll', scheduleUpdate);
    };
  }

  function setDeleteButtonState(dialog) {
    const selected = dialog.querySelectorAll('[data-pmm-preset-choice]:checked').length;
    const button = dialog.querySelector('[data-pmm-preset-delete]');
    if (!button) return;
    button.disabled = selected === 0;
    button.textContent = selected ? `删除所选（${selected}）` : '删除所选';
  }

  function filterBatchList(dialog) {
    const query = String(dialog.querySelector('[data-pmm-preset-search]')?.value || '').trim().toLocaleLowerCase();
    for (const row of dialog.querySelectorAll('.pmm-preset-batch-row')) {
      const name = String(row.dataset.pmmPresetName || '').toLocaleLowerCase();
      row.hidden = Boolean(query && !name.includes(query));
    }
  }

  async function deleteSelectedPresets(dialog, root) {
    const manager = await getPresetManagerAsync();
    if (!manager || typeof manager.deletePreset !== 'function') {
      notify('error', '当前酒馆没有提供可用的预设删除接口');
      return;
    }
    const all = getPresetNames(root, manager);
    const selected = Array.from(dialog.querySelectorAll('[data-pmm-preset-choice]:checked'))
      .map(input => String(input.value))
      .filter(name => all.includes(name));
    if (!selected.length) return;
    if (selected.length >= all.length) {
      notify('warning', '至少需要保留一个预设，不能全部删除');
      return;
    }
    const preview = selected.slice(0, 6).join('
');
    const extra = selected.length > 6 ? `
……以及另外 ${selected.length - 6} 个` : '';
    const confirmed = TOP.confirm?.(`确定删除选中的 ${selected.length} 个预设吗？

${preview}${extra}

此操作无法通过工坊撤销。`);
    if (!confirmed) return;

    const deleteButton = dialog.querySelector('[data-pmm-preset-delete]');
    const cancelButton = dialog.querySelector('[data-pmm-preset-cancel]');
    if (deleteButton) {
      deleteButton.disabled = true;
      deleteButton.textContent = '正在删除…';
    }
    if (cancelButton) cancelButton.disabled = true;
    const selectedSet = new Set(selected);
    const fallback = all.find(name => !selectedSet.has(name));
    const current = getSelectedPresetName(root, manager);
    const failed = [];
    try {
      if (selectedSet.has(current) && fallback && typeof manager.selectPreset === 'function') {
        let fallbackValue = fallback;
        try {
          const found = manager.findPreset?.(fallback);
          if (found !== undefined && found !== null) fallbackValue = found;
        } catch (_) {}
        await manager.selectPreset(fallbackValue);
      }
      for (const name of selected) {
        try { await manager.deletePreset(name); }
        catch (error) {
          failed.push(name);
          console.error(`[预设工坊] 删除预设失败：${name}`, error);
        }
      }
      const preferredName = selectedSet.has(current) ? fallback : current;
      repairPresetSelectState(root, manager, preferredName, selectedSet);
      syncSelectOptions(root);
      if (failed.length) notify('warning', `已删除 ${selected.length - failed.length} 个，另有 ${failed.length} 个删除失败`);
      else notify('success', `已删除 ${selected.length} 个预设`);
      closeBatchDialog();
      scheduleSync();
    } finally {
      if (deleteButton?.isConnected) deleteButton.disabled = false;
      if (cancelButton?.isConnected) cancelButton.disabled = false;
    }
  }

  async function openBatchDialog(root) {
    closeBatchDialog();
    const manager = await getPresetManagerAsync();
    const names = getPresetNames(root, manager);
    if (!names.length) {
      notify('warning', '暂时没有读取到可管理的预设');
      return;
    }
    const ownerDocument = (() => { try { return TOP.document || DOC; } catch (_) { return DOC; } })();
    installStyle(ownerDocument);
    const overlay = ownerDocument.createElement('div');
    overlay.className = 'pmm-preset-batch-overlay';
    overlay.innerHTML = `
      <section class="pmm-preset-batch-dialog" role="dialog" aria-modal="true" aria-label="批量管理预设">
        <header class="pmm-preset-batch-head">
          <span>批量管理预设</span>
          <button type="button" data-pmm-preset-close aria-label="关闭">×</button>
        </header>
        <input type="search" class="pmm-preset-batch-search" data-pmm-preset-search placeholder="搜索预设" autocomplete="off" enterkeyhint="search" />
        <label class="pmm-preset-batch-all"><input type="checkbox" data-pmm-preset-all />全选</label>
        <div class="pmm-preset-batch-list"></div>
        <footer class="pmm-preset-batch-footer">
          <button type="button" data-pmm-preset-cancel>取消</button>
          <button type="button" class="pmm-preset-batch-delete" data-pmm-preset-delete disabled>删除所选</button>
        </footer>
      </section>`;
    const list = overlay.querySelector('.pmm-preset-batch-list');
    const current = getSelectedPresetName(root, manager);
    for (const name of names) {
      const row = ownerDocument.createElement('label');
      row.className = 'pmm-preset-batch-row';
      row.dataset.pmmPresetName = name;
      const checkbox = ownerDocument.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = name;
      checkbox.setAttribute('data-pmm-preset-choice', '');
      const text = ownerDocument.createElement('span');
      text.textContent = name;
      row.append(checkbox, text);
      if (name === current) {
        const currentMark = ownerDocument.createElement('small');
        currentMark.textContent = '当前';
        row.appendChild(currentMark);
      }
      list.appendChild(row);
    }
    overlay.addEventListener('click', event => {
      if (event.target === overlay) closeBatchDialog();
    });
    overlay.querySelector('[data-pmm-preset-close]').addEventListener('click', closeBatchDialog);
    overlay.querySelector('[data-pmm-preset-cancel]').addEventListener('click', closeBatchDialog);
    overlay.querySelector('[data-pmm-preset-search]').addEventListener('input', () => filterBatchList(overlay));
    overlay.querySelector('[data-pmm-preset-all]').addEventListener('change', event => {
      for (const checkbox of overlay.querySelectorAll('[data-pmm-preset-choice]')) {
        const row = checkbox.closest('.pmm-preset-batch-row');
        if (!row.hidden) checkbox.checked = event.currentTarget.checked;
      }
      setDeleteButtonState(overlay);
    });
    list.addEventListener('change', () => setDeleteButtonState(overlay));
    overlay.querySelector('[data-pmm-preset-delete]').addEventListener('click', () => deleteSelectedPresets(overlay, root));
    ownerDocument.body.appendChild(overlay);
    batchDialog = overlay;
    batchDialogDocument = ownerDocument;
    bindBatchToVisibleViewport(overlay, ownerDocument);
  }

  function bindBatchTrigger(root) {
    const icon = root?.querySelector('.panel-section .fa-sliders.section-icon');
    if (!icon) return;
    icon.classList.add('pmm-preset-batch-trigger');
    icon.setAttribute('role', 'button');
    icon.setAttribute('tabindex', '0');
    icon.setAttribute('title', '批量管理预设');
    icon.setAttribute('aria-label', '批量管理预设');
    if (icon.dataset.pmmBatchBound === '1') return;
    icon.dataset.pmmBatchBound = '1';
    const open = event => {
      event.preventDefault();
      event.stopPropagation();
      void openBatchDialog(root);
    };
    icon.addEventListener('click', open);
    icon.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') open(event);
    });
  }

  function syncRoot(root) {
    if (!root) return;
    currentRoot = root;
    bindBatchTrigger(root);
    bindPresetSwitchNotice(root);
    bindAutoCollapseOnEdit(root);
    syncSelectOptions(root);
    if (isMobile()) {
      const entryEnabled = floatingEntryEnabled();
      root.classList.toggle('pmm-floating-entry-disabled', !entryEnabled);
      if (root.dataset.pmmFloatingMobileInitialized !== '1') {
        const nativePanel = root.querySelector(':scope > .panel-wrapper');
        const nativeOpen = Boolean(nativePanel && SELF.getComputedStyle(nativePanel).display !== 'none');
        root.classList.toggle('pmm-floating-mobile-open', nativeOpen);
        root.dataset.pmmFloatingMobileInitialized = '1';
      }
      if (!entryEnabled) root.classList.remove('pmm-floating-mobile-open', 'pmm-floating-dragging');
      root.classList.add('pmm-floating-mobile');
      const saved = readPosition();
      setDock(root, root.dataset.pmmFloatingDock || saved.dock, parseFloat(root.style.getPropertyValue('--pmm-mobile-floating-top')) || saved.top, false);
      bindMobileDrag(root);
    } else {
      root.classList.remove('pmm-floating-mobile', 'pmm-floating-mobile-open', 'pmm-floating-dock-left', 'pmm-floating-dock-right', 'pmm-floating-dragging', 'pmm-floating-entry-disabled');
      delete root.dataset.pmmFloatingMobileInitialized;
      root.style.removeProperty('--pmm-mobile-floating-top');
    }
  }

  function sync() {
    scheduled = 0;
    const roots = documents().flatMap(currentDocument => Array.from(currentDocument.querySelectorAll(ROOT_SELECTOR)));
    for (const root of roots) syncRoot(root);
    const mobileToolbarReady = isMobile() && floatingEntryEnabled() && roots.some(root => root?.isConnected);
    for (const currentDocument of documents()) {
      currentDocument.documentElement?.classList.toggle('pmm-mobile-toolbar-ready', mobileToolbarReady);
    }
  }

  function scheduleSync() {
    if (scheduled) return;
    scheduled = SELF.requestAnimationFrame ? SELF.requestAnimationFrame(sync) : SELF.setTimeout(sync, 16);
  }

  function installStyle(targetDocument) {
    if (!targetDocument || targetDocument.getElementById(STYLE_ID)) return;
    const style = targetDocument.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
