  box-sizing:border-box!important;width:26px!important;height:26px!important;display:inline-flex!important;
  align-items:center!important;justify-content:center!important;margin:0!important;border-radius:5px!important;
  cursor:pointer!important;color:var(--fp-text-color)!important;opacity:.8!important;font-size:11px!important;
}
