;(()=>{
  /* 预设工坊 × 柏宝箱：原子分支切换与完整分组快照 V2.53 */
  const localRoot=typeof window!=='undefined'?window:globalThis;
  let sharedRoot=localRoot;
  try{if(localRoot.top)sharedRoot=localRoot.top}catch(_){ }
  let compat=null;
  try{compat=sharedRoot.__PMM_BAIBAI_COMPAT__||localRoot.__PMM_BAIBAI_COMPAT__}
  catch(_){compat=localRoot.__PMM_BAIBAI_COMPAT__}
  if(!compat||compat.__branchTransactionV253)return;

  const PATH=compat.path||'baibaiToolkit.presetPromptGroups';
  const clone=value=>{
    try{return typeof structuredClone==='function'?structuredClone(value):JSON.parse(JSON.stringify(value))}
    catch(_){return value}
  };
  const text=value=>String(value??'');
  const unique=values=>[...new Set((values||[]).map(text).filter(Boolean))];

  function getPresetManager(){
    try{
      const context=sharedRoot.SillyTavern?.getContext?.()||localRoot.SillyTavern?.getContext?.();
      return context?.getPresetManager?.('openai')||context?.getPresetManager?.()||null
    }catch(_){return null}
  }

  function readNativeState(manager,presetName){
    try{
      const state=manager?.readPresetExtensionField?.({presetName,path:PATH});
      if(!state||!Array.isArray(state.groups)||!state.prompts||typeof state.prompts!=='object')return null;
      return clone(state)
    }catch(_){return null}
  }

  function readVariables(){
    try{return (sharedRoot.getVariables||localRoot.getVariables)?.({type:'global'})||{}}
    catch(_){return{}}
  }

  function readMainSectionState(presetName){
    const value=readVariables()[`pm_v2_groups_${presetName}`];
    return value&&typeof value==='object'?clone(value):null
  }

  function hasAppliedBranch(presetName){
    const settings=readVariables().pm_v2_settings;
    return !!settings?.bookmarks?.[presetName]
  }

  function promptsForPreset(presetName){
    try{
      const getter=sharedRoot.getPreset||localRoot.getPreset;
      const prompts=getter?.(presetName)?.prompts;
      return Array.isArray(prompts)?clone(prompts):[]
    }catch(_){return[]}
  }

  function signature(nativeState,prompts=[]){
    const raw=JSON.stringify({
      groups:(nativeState?.groups||[]).map(group=>[
        text(group?.id),
        text(group?.name??group?.title),
        group?.collapsed===true||group?.isCollapsed===true||group?.expanded===false,
        group?.enabled!==false,
      ]),
      prompts:Object.entries(nativeState?.prompts||{}).map(([id,data])=>[text(id),text(data?.groupId)]).sort((a,b)=>a[0].localeCompare(b[0])),
      promptNames:(prompts||[]).map(prompt=>[text(prompt?.id),text(prompt?.name)]).sort((a,b)=>a[0].localeCompare(b[0])),
    });
    let hash=2166136261;
    for(let i=0;i<raw.length;i++)hash=Math.imul(hash^raw.charCodeAt(i),16777619);
    return `bb47_${(hash>>>0).toString(36)}`
  }

  function normalizeSectionState(sectionState={}){
    return {
      ...clone(sectionState||{}),
      sections:clone(sectionState?.sections||[]),
      collapsedSections:unique(sectionState?.collapsedSections||[]),
      disabledSections:unique(sectionState?.disabledSections||[]),
      originalEnabledStates:clone(sectionState?.originalEnabledStates||{}),
      hasAutoClassified:sectionState?.hasAutoClassified??true,
      manualNoGroups:sectionState?.manualNoGroups??false,
      groupSource:text(sectionState?.groupSource||'none'),
      baibaiSignature:text(sectionState?.baibaiSignature||''),
    }
  }

  function snapshotBranchState({presetName='',prompts=[],sectionGroupState=null}={}){
    const fallback=normalizeSectionState(sectionGroupState||{});
    const manager=getPresetManager();
    const nativeState=readNativeState(manager,presetName);
    if(!nativeState){
      if(fallback.sections.some(section=>text(section?.id).startsWith('baibai_'))){
        fallback.groupSource='baibai';
        fallback.hasAutoClassified=true;
        fallback.manualNoGroups=false
      }
      return fallback.sections.length?fallback:sectionGroupState
    }

    const requestedPrompts=Array.isArray(prompts)?prompts:[];
    const persistedPrompts=promptsForPreset(presetName);
    const promptList=[];
    const seenPromptIds=new Set;
    for(const prompt of [...requestedPrompts,...persistedPrompts]){
      const promptId=text(prompt?.id);
      if(!promptId||seenPromptIds.has(promptId))continue;
      seenPromptIds.add(promptId);
      promptList.push(prompt)
    }
    const promptMap=new Map(promptList.map(prompt=>[text(prompt?.id),prompt]));
    const membership=new Map;
    for(const [promptId,data] of Object.entries(nativeState.prompts||{})){
      const groupId=text(data?.groupId);
      if(groupId&&promptMap.has(text(promptId)))membership.set(text(promptId),groupId)
    }

    const fallbackById=new Map((fallback.sections||[]).map(section=>[text(section?.id),section]));
    const sections=[];
    for(const group of nativeState.groups||[]){
      const groupId=text(group?.id);
      if(!groupId)continue;
      const sectionId=`baibai_${groupId}`;
      const itemIds=[];
      for(const prompt of promptList){
        const promptId=text(prompt?.id);
        if(membership.get(promptId)===groupId)itemIds.push(promptId)
      }
      const staged=fallbackById.get(sectionId);
      if(!itemIds.length&&staged?.itemIds?.length){
        for(const id of staged.itemIds)if(promptMap.has(text(id)))itemIds.push(text(id))
      }
      sections.push({
        id:sectionId,
        displayName:text(group?.name??group?.title??staged?.displayName??'新分组'),
        itemIds:unique(itemIds),
      })
    }

    for(const section of fallback.sections||[]){
      const sectionId=text(section?.id);
      if(!sectionId.startsWith('baibai_')||sections.some(item=>item.id===sectionId))continue;
      const itemIds=unique(section?.itemIds).filter(id=>promptMap.has(id));
      sections.push({...clone(section),id:sectionId,itemIds})
    }

    const collapsed=new Set(fallback.collapsedSections||[]);
    for(const group of nativeState.groups||[]){
      if(group?.collapsed===true||group?.isCollapsed===true||group?.expanded===false){
        collapsed.add(`baibai_${text(group?.id)}`)
      }
    }
    const nativeGroupIds=new Set((nativeState.groups||[]).map(group=>text(group?.id)).filter(Boolean));
    const disabled=new Set((fallback.disabledSections||[]).filter(id=>{
      const sectionId=text(id);
      return sections.some(section=>section.id===sectionId)
        && sectionId.startsWith('baibai_')
        && !nativeGroupIds.has(sectionId.slice(7))
    }));
    for(const group of nativeState.groups||[]){
      const sectionId=`baibai_${text(group?.id)}`;
      if(group?.enabled===false&&sections.some(section=>section.id===sectionId))disabled.add(sectionId)
    }

    return {
      ...fallback,
      sections,
      collapsedSections:[...collapsed].filter(id=>sections.some(section=>section.id===id)),
      disabledSections:[...disabled],
      originalEnabledStates:{},
      hasAutoClassified:true,
      manualNoGroups:false,
      groupSource:'baibai',
      baibaiSignature:signature(nativeState,promptList),
      nativeBaiBaiState:clone(nativeState),
    }
  }

  function nativeStateFromSections(sectionState,prompts,existingState){
    const normalized=normalizeSectionState(sectionState||{});
    const embedded=sectionState?.nativeBaiBaiState;
    const seed=clone(embedded&&Array.isArray(embedded.groups)?embedded:existingState)||{version:1,groups:[],prompts:{}};
    seed.version=Number(seed.version)||1;
    seed.groups=Array.isArray(seed.groups)?seed.groups.map(group=>({...group})):[];
    seed.prompts=seed.prompts&&typeof seed.prompts==='object'?{...seed.prompts}:{};

    const collapsed=new Set(normalized.collapsedSections||[]);
    const disabled=new Set(normalized.disabledSections||[]);
    const sectionGroups=[];
    for(const section of normalized.sections||[]){
      const sectionId=text(section?.id);
      if(!sectionId.startsWith('baibai_'))continue;
      const groupId=sectionId.slice(7);
      if(!groupId)continue;
      sectionGroups.push({section,sectionId,groupId})
    }
    const sectionIds=new Set(sectionGroups.map(item=>item.groupId));
    const oldById=new Map(seed.groups.map(group=>[text(group?.id),group]));
    seed.groups=sectionGroups.map(({section,sectionId,groupId})=>({
      ...(oldById.get(groupId)||{}),
      id:groupId,
      name:text(section?.displayName||oldById.get(groupId)?.name||'新分组'),
      collapsed:collapsed.has(sectionId),
      enabled:!disabled.has(sectionId),
    }));

    const promptIds=new Set((prompts||[]).map(prompt=>text(prompt?.id)).filter(Boolean));
    for(const promptId of promptIds)delete seed.prompts[promptId];
    for(const {section,groupId} of sectionGroups){
      for(const promptId of unique(section?.itemIds)){
        if(!promptIds.has(promptId))continue;
        seed.prompts[promptId]={...(existingState?.prompts?.[promptId]||embedded?.prompts?.[promptId]||{}),groupId}
      }
    }
    for(const [promptId,data] of Object.entries(seed.prompts)){
      if(promptIds.has(text(promptId))&&!sectionIds.has(text(data?.groupId)))delete seed.prompts[promptId]
    }
    return seed
  }

  async function refreshRuntime(manager,presetName,state){
    const selected=(()=>{try{return text(manager?.getSelectedPresetName?.())}catch(_){return''}})();
    if(selected&&selected!==text(presetName))return;
    const candidates=[];
    for(const root of [sharedRoot,localRoot]){
      for(const key of ['__baiBaiToolkitExtensionInstalled','__baiBaiToolkitPresetVueListManager','__baiBaiToolkitPresetVueListRenderPatch']){
        const value=root?.[key];
        if(value&&!candidates.includes(value))candidates.push(value)
      }
    }
    for(const candidate of candidates){
      try{
        if('presetPromptGroupRuntimePresetName' in candidate)candidate.presetPromptGroupRuntimePresetName=presetName;
        if('presetPromptGroupRuntimeState' in candidate)candidate.presetPromptGroupRuntimeState=clone(state);
        const promptManager=candidate?.manager||candidate?.promptManager||candidate;
        if(promptManager?.serviceSettings?.extensions){
          promptManager.serviceSettings.extensions[PATH]=clone(state)
        }
      }catch(_){ }
    }
    for(const candidate of candidates){
      const promptManager=candidate?.manager||candidate?.promptManager||candidate;
      try{
        if(typeof promptManager?.renderPromptManagerListItems==='function'){
          await promptManager.renderPromptManagerListItems();
          break
        }
      }catch(error){console.warn('[预设工坊×柏宝箱] 刷新柏宝箱列表失败:',error)}
    }
  }

  async function writeNativeState(presetName,state,{syncMembership=true,onlyGroupId=''}={}){
    const manager=getPresetManager();
    if(!manager?.writePresetExtensionField)return false;
    await manager.writePresetExtensionField({presetName,path:PATH,value:clone(state)});
    let queued=false;
    for(const group of syncMembership?(state.groups||[]):[]){
      if(onlyGroupId&&text(group?.id)!==text(onlyGroupId))continue;
      const ids=Object.entries(state.prompts||{}).filter(([,data])=>text(data?.groupId)===text(group?.id)).map(([id])=>id);
      if(!ids.length)continue;
      compat.queue?.({
        presetName,
        targetId:ids[0],
        targetPosition:'after',
        targetSectionId:`baibai_${text(group?.id)}`,
        targetGroupTitle:text(group?.name||group?.title),
        newIds:ids,
      });
      queued=true
    }
    if(queued)await compat.flushPreset?.(presetName);
    else await refreshRuntime(manager,presetName,state);
    return true
  }

  async function applyBranchState(presetName,sectionGroupState,prompts=[]){
    if(!sectionGroupState||text(sectionGroupState.groupSource)!=='baibai'&&!sectionGroupState.sections?.some(section=>text(section?.id).startsWith('baibai_')))return false;
    const manager=getPresetManager();
    const existing=readNativeState(manager,presetName);
    const native=nativeStateFromSections(sectionGroupState,prompts,existing);
    return writeNativeState(presetName,native,{syncMembership:false})
  }

  async function restoreMainState(presetName){
    const sectionState=readMainSectionState(presetName);
    if(!sectionState)return false;
    return applyBranchState(presetName,sectionState,promptsForPreset(presetName))
  }

  let branchTransactionSerial=0;
  const branchTransactions=new Map;

  function beginBranchSwitch(presetName=''){
    const token=++branchTransactionSerial;
    branchTransactions.set(token,text(presetName));
    return token
  }

  function endBranchSwitch(token){
    if(token!=null)branchTransactions.delete(token)
  }

  function isBranchSwitching(presetName=''){
    if(!branchTransactions.size)return false;
    const requested=text(presetName);
    if(!requested||requested==='in_use')return true;
    for(const activePreset of branchTransactions.values()){
      if(!activePreset||activePreset===requested)return true
    }
    return false
  }

  async function syncEnabledStates({presetName='',prompts=[]}={}){
    if(!presetName||!Array.isArray(prompts)||hasAppliedBranch(presetName))return false;
    const setter=sharedRoot.setPreset||localRoot.setPreset;
    if(typeof setter!=='function')return false;
    const copy=clone(prompts);
    await setter(presetName,{prompts:copy});
    const loaded=(()=>{try{return text((sharedRoot.getLoadedPresetName||localRoot.getLoadedPresetName)?.())}catch(_){return''}})();
    if(loaded===text(presetName))await setter('in_use',{prompts:clone(copy)});
    await refreshRuntime(getPresetManager(),presetName,readNativeState(getPresetManager(),presetName)||{groups:[],prompts:{}});
    return true
  }

  function resolveNativePresetName(presetName){
    const requested=text(presetName);
    if(requested&&!requested.startsWith('branch:'))return requested;
    try{
      const loaded=text((sharedRoot.getLoadedPresetName||localRoot.getLoadedPresetName)?.());
      if(loaded&&loaded!=='in_use')return loaded
    }catch(_){ }
    try{return text(getPresetManager()?.getSelectedPresetName?.())}
    catch(_){return''}
  }

  async function syncGroupEnabledState({presetName='',sectionId='',enabled=true}={}){
    const resolvedPreset=resolveNativePresetName(presetName);
    const rawSectionId=text(sectionId);
    const groupId=rawSectionId.startsWith('baibai_')?rawSectionId.slice(7):rawSectionId;
    if(!resolvedPreset||!groupId)return false;
    const manager=getPresetManager();
    const state=readNativeState(manager,resolvedPreset);
    if(!state)return false;
    const group=(state.groups||[]).find(item=>text(item?.id)===groupId);
    if(!group)return false;
    group.enabled=enabled!==false;
    /* 仅排入当前分组以触发原生列表即时刷新；提示固定为一句，避免罗列全部分组。 */
    compat.__nextSuccessMessage='分组开关已同步';
    try{return await writeNativeState(resolvedPreset,state,{onlyGroupId:groupId})}
    finally{delete compat.__nextSuccessMessage}
  }

  Object.assign(compat,{
    __branchStateSyncV247:true,
    __groupPowerSyncV250:true,
    __promptNameSyncV251:true,
    __branchTransactionV253:true,
    beginBranchSwitch,
    endBranchSwitch,
    isBranchSwitching,
    snapshotBranchState,
    applyBranchState,
    restoreMainState,
    syncEnabledStates,
    syncGroupEnabledState,
    nativeStateFromSections,
  });
  try{sharedRoot.__PMM_BAIBAI_COMPAT__=compat}catch(_){ }
  localRoot.__PMM_BAIBAI_COMPAT__=compat;
  console.info('[预设工坊×柏宝箱] V2.53 已加载：新分支保留完整柏宝箱分组，分支切换改为单写入事务。')
})();
